/*
 * 世界史探究(地域・時代別にくわしく・前半)のテキスト本文。このアプリのオリジナル。
 * 書式は lessons_1.js 冒頭のコメントと同じ。drill は練習問題({lv, q, a, exp})。
 * 図解(flow・tmap・chain)の書式は lessons_zukai.js を参照。
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ===== 古代オリエントと地中海世界 =====
  L.wh_orient = {
    goal: 'メソポタミア・エジプトの文明の特徴、オリエント統一の流れ、ギリシアの民主政とローマの共和政・帝政の成り立ちを、「だれが戦い、だれが政治に参加したか」という因果で説明できるようになる。',
    intro: '古代の歴史は、遠い昔の話に見えます。でも、私たちが使う「1時間=60分」は古代メソポタミアの六十進法から、「1年=365日」はエジプトの太陽暦から、アルファベットはフェニキア人の文字から来ています。「民主政」や「共和政」ということばも、ギリシア・ローマの政治から生まれました。\nこの単元では、大きな川のほとりで生まれた文明が、やがて地中海をかこむ大きな世界にまとまっていく流れを追いかけます。カギは【「戦争に参加した人が、政治にも参加するようになる」】という考え方です。これが分かると、アテネの民主政もローマの身分闘争も一本の筋でつながります。',
    pre: '【オリエント】とは、ラテン語で「日がのぼる方角(東方)」という意味で、ヨーロッパから見て東にある、今の西アジアとエジプトの地域を指します。\n【文明】が生まれるには、食料の余り(余剰生産物)が必要です。大きな川の流域では、洪水が運ぶ肥えた土と水を利用して灌漑農業ができ、多くの食料がとれました。食料に余りが出ると、農業以外の仕事をする神官・戦士・職人が生まれ、都市・文字・国家ができました。\n年代の表し方にも注意しましょう。【紀元前(前)】は西暦1年より前で、数字が大きいほど古くなります。前3000年は前500年より古い時代です。「前5世紀」は前500年〜前401年を指します。\n宗教では、多くの神を信じる【多神教】と、ただ一つの神を信じる【一神教】を区別します。古代オリエントの多くは多神教で、ヘブライ人のユダヤ教が一神教の代表です。\n中学では「四大文明」として、メソポタミア・エジプト・インダス・中国の文明を学びました。この単元では、そのうちメソポタミアとエジプトを中心に、さらにギリシア・ローマまで広げます。',
    secs: [
      { h: 'メソポタミア文明:開かれた地形と興亡', t: 'なぜメソポタミアでは王朝の交代が激しかったのでしょうか。メソポタミアは「川のあいだの地」という意味で、【ティグリス川】と【ユーフラテス川】の流域を指します。まわりを山や砂漠で守られていない【開放的な地形】だったため、周辺からさまざまな民族が入ってきて、国の興亡がくり返されました。\n前3000年ごろまでに、【シュメール人】がウルやウルクなどの都市国家をつくりました。都市の中心には、神をまつる聖塔【ジッグラト】が建てられ、王は神の代理として政治を行いました(神権政治)。\nシュメール人は、粘土板に葦のペンで刻む【楔形文字】を発明しました。月の満ち欠けにもとづく【太陰暦】や、60を単位とする【六十進法】も使いました。六十進法は、今の時間や角度の数え方に受けつがれています。\nその後、セム語系のアッカド人がメソポタミアを統一し、さらに前19世紀ごろにはアムル人がバビロン第1王朝(古バビロニア王国)をおこしました。前18世紀ごろの【ハンムラビ王】は全メソポタミアを支配し、【ハンムラビ法典】を定めました。\nハンムラビ法典は「目には目を、歯には歯を」という【同害復讐】の原則で有名ですが、同じ罪でも、被害者や加害者の身分によって刑罰が異なりました。「すべての人を平等にあつかった法」ではないことに注意しましょう。\n前17世紀ごろには、インド=ヨーロッパ語系の【ヒッタイト人】がアナトリア(小アジア)に国をつくり、早くから【鉄器】を使って勢力をのばしました。',
        key: 'メソポタミアは開放的な地形のため民族の出入りが激しい。シュメール人の楔形文字・六十進法、ハンムラビ法典(同害復讐・身分で刑罰が異なる)をおさえる。',
        ex: [{ q: 'ハンムラビ法典について、「同害復讐の原則で、すべての人に同じ刑罰を科した」という説明は正しいか。誤りがあれば正しく直そう。', hint: '「同害復讐」と「身分」の2つの要素に分けて確かめましょう。', steps: ['ハンムラビ法典は、前18世紀ごろバビロン第1王朝のハンムラビ王が定めた。', '「目には目を、歯には歯を」という同害復讐が原則なので、前半は正しい。', 'しかし刑罰は、被害者と加害者の身分(貴族・平民・奴隷など)によって異なっていた。', 'したがって「すべての人に同じ刑罰」の部分が誤り。'], a: '誤り。同害復讐が原則だったが、刑罰は身分によって異なっていた。', check: '正誤問題では、文を「前半」と「後半」に分け、両方とも正しいときだけ「正しい」と判断します。' }] },
      { h: 'エジプト文明:閉じた地形と長く続く王国', t: 'メソポタミアと反対に、エジプトは東西を砂漠、北を海に囲まれた【閉鎖的な地形】でした。外敵が入りにくかったため、同じしくみの王国が長く続きました。\nエジプトの農業は、毎年決まった時期に起こる【ナイル川】の増水にささえられていました。増水は肥えた土を運んでくるため、ギリシアの歴史家【ヘロドトス】は「エジプトはナイルのたまもの」と述べました。\n増水の時期を正確に知る必要から、1年を365日とする【太陽暦】が生まれました。また、増水のあとに農地の境界を測り直す必要から、測地術(のちの幾何学)が発達しました。太陽暦はのちにローマに伝わり、今の暦のもとになりました。\n王は【ファラオ】とよばれ、生きている神として神権政治を行いました。前27世紀ごろからの古王国の時代には、クフ王などが巨大な【ピラミッド】を建てました。\nエジプト人は、霊魂が不滅であると考えて死後の世界を重んじ、遺体を【ミイラ】にして保存し、死後の審判に備えるための『死者の書』を墓に納めました。文字には、碑文などに使う【神聖文字(ヒエログリフ)】と、パピルスに書く民用文字などがありました。\n新王国の時代、前14世紀の【アメンホテプ4世】は、都の神アメンの神官団の力をおさえるため、唯一の神【アトン】を信仰させ、都をテル=エル=アマルナに移しました。この時期の写実的な美術をアマルナ美術といいます。ただし、この改革は王の死後に元にもどりました。',
        key: 'エジプトは閉鎖的な地形で王国が長続き。ナイルの増水から太陽暦と測地術。ファラオの神権政治、ピラミッド、ミイラと『死者の書』、アメンホテプ4世のアトン信仰。' },
      { h: '東地中海の民族と、オリエントの統一', t: 'メソポタミアとエジプトのあいだにある東地中海の沿岸(シリア・パレスチナ)では、セム語系の民族が交易や宗教で活躍しました。この地域は二つの大文明をつなぐ「通り道」だったからです。\n【アラム人】は、ダマスクスを中心に内陸の中継貿易で活動しました。そのためアラム語は国際的な商業語になり、アラム文字は東方の多くの文字のもとになりました。\n【フェニキア人】は、シドンやティルスを拠点に地中海で海上交易を行い、北アフリカに【カルタゴ】などの植民市をつくりました。フェニキア人の文字は、ギリシアに伝わって【アルファベット】のもとになりました。\n【ヘブライ人】は、唯一神ヤハウェを信じる【ユダヤ教】をつくりあげました。前6世紀に新バビロニアに征服されて人々がバビロンに連れ去られた【バビロン捕囚】などの苦難の中で、自分たちだけが神に救われるという選民思想や、救世主(メシア)を待ち望む信仰が強まりました。その教えは『旧約聖書』にまとめられ、のちのキリスト教・イスラーム教に大きな影響を与えました。\n前7世紀前半には、【アッシリア】がはじめてオリエント全体を統一しました。しかし重税と力による支配に反発が強く、アッシリアが滅びると、オリエントはエジプト・リディア・新バビロニア・メディアの4王国に分かれました。\n前6世紀後半には、イラン人の【アケメネス朝ペルシア】がふたたびオリエントを統一しました。最盛期の【ダレイオス1世】は、全国を州に分けて知事【サトラップ】をおき、「王の目」「王の耳」とよばれる監察官に見回らせました。都スサなどを結ぶ【王の道】を整え、駅伝制を設けました。服属した民族には、税と兵を出せば宗教や習慣を認める【寛容な支配】を行い、これがアッシリアとのちがいです。宗教では、善と悪の神の戦いを説く【ゾロアスター教】が信仰されました。',
        key: 'アラム人=内陸の中継貿易、フェニキア人=海上交易とアルファベット、ヘブライ人=一神教のユダヤ教。統一はアッシリア(力の支配)→ 4王国分立 → アケメネス朝(寛容な支配)。',
        flow: { title: '古代オリエントの流れ(上から下へ)', cols: 2, head: ['メソポタミア・西アジア', 'エジプト'], rows: [
          [['シュメール人の都市国家', 'b', 1, '前3000年ごろ・楔形文字'], ['古王国', 'g', 1, 'ピラミッド']],
          [['バビロン第1王朝', 'b', 1, 'ハンムラビ王(前18世紀ごろ)'], ['中王国', 'g']],
          [['ヒッタイト(鉄器)など', 'b'], ['新王国', 'g', 1, 'アメンホテプ4世(前14世紀)']],
          [['アッシリアがはじめてオリエントを統一', 'k', 2, '前7世紀前半']],
          [['新バビロニア・メディア・リディア', 'b', 1, '4王国の分立'], ['エジプト', 'g']],
          [['アケメネス朝ペルシアが再統一', 'rr', 2, '前6世紀後半・ダレイオス1世']],
          [['アレクサンドロス大王が征服', 'r', 2, '前330年アケメネス朝が滅亡']]
        ], legend: [['b', 'メソポタミア・西アジア'], ['g', 'エジプト'], ['k', 'オリエントの統一'], ['rr', '再統一'], ['r', 'ギリシア勢力']] } },
      { h: 'ギリシア:ポリスと民主政のなりたち', t: 'ギリシアは山が多く平野がせまいため、統一国家ではなく、【ポリス】(都市国家)が数多く分立しました。ポリスは、丘の上の神殿(アクロポリス)と広場(アゴラ)を中心にした共同体で、市民は同じ言語や神々、オリンピアの祭典などを通じて「ヘレネス(ギリシア人)」としての仲間意識をもっていました。\nなぜアテネで民主政が発展したのでしょうか。カギは【戦い方】です。ポリスの軍隊の中心は、自分で武具を買いそろえる【重装歩兵】で、豊かになった平民がその役割をになうようになりました。ポリスを守る兵士になった平民は、「自分たちにも政治に参加する権利がある」と主張し、貴族と対立しました。\n前6世紀初めの【ソロン】は、借金で市民が奴隷になることを禁じ、財産額に応じて政治参加の権利を決める改革を行いました。その後、平民の支持を受けて独裁を行う【僭主】のペイシストラトスが現れました。前6世紀末の【クレイステネス】は、血縁の4部族を地縁の10部族に改め、僭主になりそうな人物を投票で国外に追放する【陶片追放(オストラシズム)】をつくりました。\n前5世紀前半の【ペルシア戦争】では、アケメネス朝の大軍をギリシア側がしりぞけました。前490年のマラトンの戦いでは重装歩兵が活躍し、前480年の【サラミスの海戦】では、軍船(三段櫂船)のこぎ手となった、財産のない【無産市民】が勝利に貢献しました。こうして無産市民の発言力も強まりました。\n前5世紀半ばの【ペリクレス】の時代に、アテネ民主政は完成しました。18歳以上の成年男性市民が参加する【民会】が最高の議決機関で、役人の多くは【抽選】で選ばれました。市民が直接決める【直接民主政】です。ただし、女性・奴隷・在留外人には参政権がありませんでした。\n一方、【スパルタ】は、少数の市民が多数の隷属農民(ヘイロータイ)を支配するため、きびしい軍国主義の体制をとりました。アテネを中心とするデロス同盟とスパルタを中心とするペロポネソス同盟は、【ペロポネソス戦争】(前431〜前404年)で争い、スパルタが勝ちましたが、ポリスどうしの争いでギリシアは衰えていきました。',
        key: '重装歩兵(平民)→ 三段櫂船のこぎ手(無産市民)と、戦う人が広がるたびに参政権も広がった。完成したアテネ民主政は成年男性市民による直接民主政。',
        chain: { title: 'アテネ民主政への道', items: [
          ['背景', '商工業の発達で豊かになった平民が、武具を自分でそろえて重装歩兵になる', '平民が「政治に参加させよ」と貴族に要求'],
          ['改革', 'ソロンの改革(前6世紀初め)', '債務奴隷の禁止・財産額に応じた参政権'],
          ['改革', 'クレイステネスの改革(前6世紀末)', '地縁の10部族・陶片追放'],
          ['できごと', 'ペルシア戦争・サラミスの海戦(前480年)', '三段櫂船のこぎ手として無産市民が活躍'],
          ['結果', 'ペリクレスの時代に民主政が完成(前5世紀半ば)', '民会が最高機関・役人は抽選・ただし女性や奴隷は除く']] },
        ex: [{ q: 'サラミスの海戦のあと、アテネで無産市民の政治的な発言力が強まったのはなぜか。説明しよう。', hint: '軍船を動かしたのはだれか、を考えましょう。', steps: ['サラミスの海戦(前480年)は、アテネの海軍がペルシア軍を破った戦い。', '軍船の三段櫂船は、多くのこぎ手の力で動いた。', 'こぎ手には武具が不要なので、財産のない無産市民がこの役割をになった。', '国を守った無産市民は、政治に参加する権利を強く主張できるようになった。'], a: '三段櫂船のこぎ手として無産市民が勝利に貢献し、国防の担い手になったことで、政治参加を求める発言力が強まったから。', check: '「戦争に参加した人が政治にも参加する」という因果で、重装歩兵と平民の関係にも同じ説明が当てはまるかを確かめます。' }] },
      { h: 'ヘレニズム時代:東西の文化が混ざる', t: 'ポリスどうしの争いで力の弱まったギリシアに、北方の【マケドニア】が進出しました。フィリッポス2世は、前338年のカイロネイアの戦いでアテネ・テーベの連合軍を破り、ギリシアの大部分を支配下におきました。\nその子【アレクサンドロス大王】は、前334年に東方遠征を始め、アケメネス朝ペルシアを滅ぼし(前330年)、エジプトからインド北西部にいたる大帝国をつくりました。各地にアレクサンドリアという名の都市を建て、ペルシア人との結婚を奨励するなど、東西の融合をはかりました。\n大王が若くして亡くなると、帝国は後継者(ディアドコイ)たちによって、アンティゴノス朝マケドニア、セレウコス朝シリア、プトレマイオス朝エジプトなどに分かれました。\n大王の東方遠征からプトレマイオス朝が滅びる前30年までの約300年間を【ヘレニズム時代】といいます。ギリシア文化がオリエントに広まり、オリエントの文化と混じり合って、新しい【ヘレニズム文化】が生まれました。\nヘレニズム文化の中心は、エジプトの【アレクサンドリア】でした。王立研究所(ムセイオン)では自然科学が発達し、エウクレイデス(ユークリッド)が平面幾何学を大成し、アルキメデスが浮力の原理を発見しました。思想では、ポリスの枠をこえて、個人の心の安らぎを求めるストア派やエピクロス派が生まれ、世界市民主義(コスモポリタニズム)の考えが広まりました。\nヘレニズムの彫刻は、のちにインドのガンダーラ美術にも影響を与えました。このように、ヘレニズムは「ギリシアと東方をつなぐ橋」の役割をはたしました。',
        key: 'アレクサンドロス大王の東方遠征(前334年〜)で、ギリシア文化とオリエント文化が融合したヘレニズム文化が生まれた。中心はアレクサンドリア。' },
      { h: 'ローマ:共和政から帝政へ', t: 'イタリア半島の都市国家ローマは、前509年に王を追放して【共和政】を始めました。最高の官職は任期1年・定員2名の【執政官(コンスル)】で、貴族の会議である【元老院】が実質的な権力をにぎっていました。\nギリシアと同じように、ローマでも平民が重装歩兵として活躍するようになり、権利の拡大を求めました(身分闘争)。平民を守るための【護民官】と平民会が設けられ、前5世紀半ばには慣習法を成文化した【十二表法】がつくられました。前367年の【リキニウス・セクスティウス法】で執政官の1人を平民から選ぶ道が開かれ、前287年の【ホルテンシウス法】で、平民会の決議が元老院の承認なしに国法となりました。\nローマは前3世紀前半にイタリア半島を統一し、さらに【ポエニ戦争】(前264〜前146年)でフェニキア人の植民市カルタゴを破って、西地中海を支配しました。征服した海外の領土は【属州】とよばれました。\nしかし、この拡大が共和政をゆるがします。長い遠征で中小農民の農地は荒れ、属州から安い穀物が入ってきたうえに、有力者が奴隷を使う大農場【ラティフンディア】を経営したため、中小農民は没落しました。重装歩兵の中心だった中小農民が減ったことで、軍隊は財産のない人々を雇う職業軍人の軍隊に変わり、有力な政治家が私兵のように軍を率いるようになりました。\n前2世紀後半の【グラックス兄弟】は、大土地所有を制限して農民を立て直そうとしましたが失敗しました。こうして約100年にわたる「内乱の1世紀」が始まります。【カエサル】は独裁権をにぎりましたが前44年に暗殺され、その養子の【オクタウィアヌス】が前31年のアクティウムの海戦でアントニウスとクレオパトラを破り、地中海世界を統一しました。\n前27年、オクタウィアヌスは元老院から【アウグストゥス(尊厳者)】の称号を受けました。彼は共和政の形を残しながら、「市民の中の第一人者」として実際にはすべての権力をにぎりました。これを【元首政(プリンキパトゥス)】といい、ここからローマは帝政の時代に入ります。',
        key: '平民が重装歩兵 → 身分闘争で平等へ(ホルテンシウス法・前287年)。拡大 → 中小農民の没落 → 軍の私兵化 → 内乱の1世紀 → アウグストゥスの元首政(前27年)。',
        flow: { title: 'ローマの政治体制の移り変わり', cols: 3, rows: [
          [['王政', 'k', 1, '〜前509年'], ['共和政', 'b', 1, '執政官・元老院'], ['身分闘争', 'b', 1, '十二表法〜ホルテンシウス法(前287年)']],
          [['ポエニ戦争', 'r', 1, '前264〜前146年'], ['中小農民の没落', 'r', 1, 'ラティフンディア・属州の穀物'], ['内乱の1世紀', 'r', 1, 'グラックス兄弟〜カエサル']],
          [['元首政', 'g', 1, 'アウグストゥス(前27年〜)'], ['パクス=ロマーナ', 'g', 1, '約200年の平和・五賢帝'], ['3世紀の危機', 'k', 1, '軍人皇帝']],
          [['専制君主政', 'o', 1, 'ディオクレティアヌス帝'], ['キリスト教公認', 'o', 1, 'ミラノ勅令(313年)'], ['東西分裂', 'o', 1, '395年 → 西は476年に滅亡']]
        ], legend: [['b', '共和政の発展'], ['r', '拡大と危機'], ['g', '帝政の繁栄'], ['o', '帝政後期']] },
        ex: [{ q: 'ローマの共和政がくずれていった理由を、「中小農民」ということばを使って説明しよう。', hint: '中小農民は、ローマ軍の中で何の役割をしていたかを思い出しましょう。', steps: ['共和政のローマでは、中小農民が重装歩兵として軍の中心だった。', 'ポエニ戦争などの長い遠征で農地が荒れ、属州からの安い穀物やラティフンディアとの競争に負けて、中小農民は没落した。', '軍隊は財産のない人を雇う職業軍人の軍隊に変わり、兵士は将軍個人に従うようになった。', '有力な将軍どうしが争う内乱が続き、元老院中心の共和政が機能しなくなった。'], a: '重装歩兵として軍の中心だった中小農民が、遠征と大土地所有の広がりで没落したため、軍が有力者の私兵のようになり、有力者どうしの内乱で元老院中心の共和政がくずれた。', check: '「中小農民の没落 → 軍のしくみの変化 → 内乱」と、3つの段階がつながっているかを確かめます。' }] },
      { h: 'もっと深く:ローマ帝国の繁栄・変質とキリスト教', t: 'アウグストゥスから約200年間、地中海世界は平和と繁栄の時代をむかえました。これを【パクス=ロマーナ(ローマの平和)】といいます。とくに1世紀末からの【五賢帝】の時代が最盛期で、トラヤヌス帝のときに帝国の領土は最大になりました。212年には、帝国内の全自由民にローマ市民権が与えられました。\nローマは実用的な文化にすぐれ、道路・水道・コロッセウムなどの建築や、のちのヨーロッパの法の土台となる【ローマ法】を残しました。\n3世紀になると、各地の軍隊が皇帝を立てては倒す【軍人皇帝】の時代となり、帝国は混乱しました(3世紀の危機)。284年に即位した【ディオクレティアヌス帝】は、帝国を4つに分けて統治し、皇帝を神のようにあがめさせる【専制君主政(ドミナトゥス)】を始めました。元首政の「市民の第一人者」から、市民の上に立つ専制君主へと、皇帝のあり方が変わったのです。\nこの時期に広まったのが【キリスト教】です。1世紀にパレスチナで【イエス】が神の愛と隣人愛を説き、ユダヤ教の形式主義を批判しました。イエスが十字架にかけられたあと、ペテロやパウロらの使徒が布教し、教えは『新約聖書』にまとめられました。キリスト教徒は皇帝崇拝を拒んだため迫害されましたが、下層民や女性を中心に広がりました。\n313年、【コンスタンティヌス帝】は【ミラノ勅令】でキリスト教を公認しました。帝国の統一を保つには、広まった信仰を味方にしたほうがよいと考えたのです。325年には【ニケーア公会議】を開き、神とイエスを同じ本質とみる【アタナシウス派】を正統とし、アリウス派を異端としました。330年には都をビザンティウムに移し、コンスタンティノープルと改めました。\n392年、【テオドシウス帝】はキリスト教を国教とし、ほかの宗教を禁じました。彼が395年に亡くなると、帝国は【東西に分裂】しました。西ローマ帝国は、ゲルマン人の移動による混乱の中、476年にゲルマン人の傭兵隊長オドアケルによって滅ぼされました。東ローマ(ビザンツ)帝国は、その後も約1000年続きます。',
        key: '元首政(アウグストゥス)→ 専制君主政(ディオクレティアヌス)。キリスト教は 313年公認(コンスタンティヌス)→ 325年ニケーア公会議 → 392年国教化(テオドシウス)→ 395年東西分裂。' },
      { h: '入試ではこう出る:政治のしくみの比較と正誤問題', t: '古代の地中海世界では、【比較】の問題がよく出ます。とくに「アテネとスパルタ」「アテネの民主政と現代の民主政治」「ローマの元首政と専制君主政」「アッシリアとアケメネス朝の支配」は定番です。\n比較問題の解き方は、比べる観点を先に決めることです。政治のしくみなら、(1)だれが参加できたか、(2)どうやって決めたか、(3)何が権力の土台だったか、の3つを観点にすると、ほとんどの問題に対応できます。\n正誤問題で多いひっかけは、【人物とできごとの入れかえ】です。ミラノ勅令(コンスタンティヌス帝)と国教化(テオドシウス帝)、陶片追放(クレイステネス)と民主政の完成(ペリクレス)、リキニウス・セクスティウス法(前367年)とホルテンシウス法(前287年)などが入れかえられやすい組み合わせです。\n論述問題では、「〜の理由を説明せよ」が多く出ます。その場合は、この単元で使った「戦う人が広がる → 参政権も広がる」「征服の拡大 → 中小農民の没落 → 内乱」のような因果の鎖を、そのまま答案の骨組みにします。\n年代並べかえの問題では、まず大きな区切り(オリエント統一 → ペルシア戦争 → ヘレニズム → ローマの地中海統一)を決めてから、その中の順番を考えると迷いません。',
        key: '比較は「だれが参加・どう決める・何が土台」の3観点で。正誤は人物とできごとの入れかえに注意。',
        ex: [
          { q: 'アッシリアとアケメネス朝ペルシアの、服属した民族に対する支配のしかたのちがいを説明しよう。', hint: 'どちらの帝国が長続きしたかも考えましょう。', steps: ['アッシリアは前7世紀前半にはじめてオリエントを統一したが、重税と強制移住など、力で押さえつける支配を行った。', 'そのため服属民の反発をまねき、短い期間で滅び、4王国に分かれた。', 'アケメネス朝は、税と兵を出せば、服属した民族の宗教や習慣を認める寛容な支配を行った。', 'あわせて、サトラップや「王の目」「王の耳」、王の道などで中央の統制も強めた。'], a: 'アッシリアは力による支配で反発をまねき短期間で滅んだが、アケメネス朝は服属民の宗教や習慣を認める寛容な支配と、サトラップなどによる中央集権を組み合わせて広い領域を治めた。', check: '「支配のしかた」と「その結果(長続きしたかどうか)」の両方が答えに入っているかを確かめます。' },
          { q: '次のできごとを古い順に並べよう。ア ホルテンシウス法の制定 イ ミラノ勅令 ウ アウグストゥスの称号を受ける エ ポエニ戦争の開始', hint: 'まず「共和政」と「帝政」のどちらの時代かで2つに分けましょう。', steps: ['共和政の時代のできごとは、ア(前287年)とエ(前264年)。', '帝政の時代のできごとは、ウ(前27年)とイ(313年)。', '共和政の中では、ア(前287年)がエ(前264年)より古い。', '帝政の中では、ウ(前27年)がイ(313年)より古い。'], a: 'ア → エ → ウ → イ', check: '紀元前は数字が大きいほど古いことに注意して、前287 → 前264 → 前27 → 313 と並んでいるかを確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: 'シュメール人が発明し、粘土板に刻んだ文字を何という?', a: '楔形文字', exp: '楔形文字は、葦のペンを粘土板に押しあてて刻むため、くさびのような形になります。\nシュメール人のあとも、メソポタミアの多くの民族に使われ、ハンムラビ法典も楔形文字で刻まれています。エジプトの神聖文字(ヒエログリフ)と区別しましょう。' },
      { lv: 1, q: 'アテネ民主政の完成期に、最高の議決機関として成年男性市民が参加した会議を何という?', a: '民会', exp: 'ペリクレスの時代のアテネでは、成年男性市民が民会に直接参加して重要なことを決めました。これを直接民主政といいます。\nただし、女性・奴隷・在留外人は参加できませんでした。「全員が参加できた」とする選択肢は誤りです。' },
      { lv: 2, q: 'エジプトで太陽暦が生まれた理由を、ナイル川と関連づけて説明しよう。', a: '農業をささえるナイル川の増水が毎年ほぼ決まった時期に起こるため、その時期を正確に知って種まきなどの準備をする必要があったから。', exp: 'エジプトの農業は、ナイル川の定期的な増水が運ぶ肥えた土にささえられていました。\n増水の時期を正確に予測するため、天体の観測から1年を365日とする太陽暦がつくられました。同じく、増水のあとに農地の境界を測り直す必要から測地術が発達しています。\n「文明の技術は、その土地の必要から生まれた」という見方で、メソポタミアの六十進法や太陰暦とあわせて整理しておきましょう。' },
      { lv: 2, q: 'ヘレニズム文化の特徴を、「ポリス」ということばを使って説明しよう。', a: 'ギリシア文化がオリエントに広まって混じり合った文化で、ポリスの枠をこえた世界市民主義や、個人の心の安らぎを求める思想が広まった。', exp: 'アレクサンドロス大王の東方遠征によって、ギリシア人の生活の舞台はポリスから大帝国へと広がりました。\nその結果、「ポリスの市民」としてではなく「世界の市民」として生きる世界市民主義(コスモポリタニズム)や、ストア派・エピクロス派のように個人の内面を重んじる思想が生まれました。\n自然科学では、アレクサンドリアのムセイオンを中心にエウクレイデスやアルキメデスが活躍しました。' },
      { lv: 3, q: 'アテネとローマでは、どちらも平民の政治的な権利が拡大した。その共通の背景を60字程度で説明しよう。(記述)', a: '(模範解答)商工業や農業で力をつけた平民が、武具を自分でそろえる重装歩兵として国の防衛をになうようになり、その役割を根拠に政治参加を求めたから。(66字)', exp: 'アテネでもローマでも、軍隊の中心は自分で武具を用意する重装歩兵でした。豊かになった平民がこの役割をにない、「国を守っているのだから政治にも参加させよ」と貴族に要求したのが共通点です。\nアテネではさらに、サラミスの海戦で三段櫂船のこぎ手になった無産市民の発言力も強まりました。ローマでは、護民官・十二表法・リキニウス・セクスティウス法・ホルテンシウス法と段階的に平等が進みました。\n採点のポイントは、(1)平民が重装歩兵として軍の中心になった、(2)国防の役割が政治参加の要求の根拠になった、の2点です。「平民が増えたから」だけでは、なぜ発言力が強まったのかが説明できていないので不十分です。' },
      { lv: 3, q: '元首政と専制君主政のちがいを、皇帝の位置づけに注目して説明しよう。(記述)', a: '(模範解答)元首政はアウグストゥスが始めた体制で、共和政の形を残し、皇帝は「市民の中の第一人者」として元老院を尊重した。専制君主政はディオクレティアヌス帝が始めた体制で、皇帝は神のようにあがめられ、市民の上に立って専制的に支配した。', exp: '元首政(プリンキパトゥス)の「元首(プリンケプス)」は「第一の市民」という意味です。アウグストゥスは実際には全権力をにぎりましたが、共和政の伝統に配慮して、元老院などのしくみを残しました。\n3世紀の危機をへて即位したディオクレティアヌス帝は、帝国を立て直すため、皇帝を神のように礼拝させ、元老院の形式も軽んじる専制君主政(ドミナトゥス)を始めました。\n採点のポイントは、(1)元首政=共和政の形を残した「第一人者」、(2)専制君主政=神のような専制君主、(3)それぞれの始めた皇帝、の3点です。' }
    ],
    faq: [
      ['アテネの民主政は、今の民主政治と同じものなの?', '同じではありません。アテネは市民が民会に直接参加する【直接民主政】で、役人の多くを抽選で選びました。今の日本は、選挙で選んだ代表が議会で決める【間接民主政(議会制民主主義)】です。\nまた、アテネで参政権をもったのは成年男性市民だけで、女性・奴隷・在留外人は除かれていました。'],
      ['「オリエントの統一」は何回あったの?', '教科書でおさえるのは2回です。前7世紀前半の【アッシリア】がはじめての統一、その後4王国に分かれ、前6世紀後半の【アケメネス朝ペルシア】がふたたび統一しました。\nアケメネス朝は前330年にアレクサンドロス大王に滅ぼされ、オリエントはギリシア系の王朝が治めるヘレニズム時代に入ります。'],
      ['ローマ帝国はいつ滅びたの?', '395年に東西に分かれ、【西ローマ帝国】は476年に滅びました。一方、【東ローマ(ビザンツ)帝国】は、首都コンスタンティノープルを中心に続き、1453年にオスマン帝国に滅ぼされるまで約1000年続きました。\n「ローマ帝国の滅亡」と聞かれたら、東西どちらのことかを必ず確かめましょう。']
    ],
    terms: [['オリエント', '「日がのぼる方角」の意味。ヨーロッパから見た東方で、西アジアとエジプトの地域'], ['楔形文字', 'シュメール人が発明し、粘土板に刻んだ文字'], ['ファラオ', '古代エジプトの王。生きている神として神権政治を行った'], ['サトラップ', 'アケメネス朝が各州においた知事'], ['ポリス', '古代ギリシアの都市国家。アクロポリスとアゴラを中心とする共同体'], ['陶片追放', '僭主になりそうな人物を、陶片に名前を書く投票で国外に追放する制度'], ['ラティフンディア', 'ローマの有力者が奴隷を使って経営した大農場'], ['元首政', 'アウグストゥスが始めた、共和政の形を残しながら皇帝が実権をにぎる体制']],
    miss: ['ハンムラビ法典を「身分に関係なく平等な法」と思う。同害復讐が原則だが、刑罰は身分によって異なった。「同害復讐」と「身分差」をセットで覚える。', 'アラム人とフェニキア人の活動を取りちがえる。アラム人=陸(内陸の中継貿易)、フェニキア人=海(海上交易・カルタゴ)と、陸と海で区別する。', 'アテネ民主政では女性も参政権をもっていたと思う。参加できたのは成年男性市民だけ。現代の民主政治と比べる問題で特にねらわれる。', 'ミラノ勅令(公認・313年・コンスタンティヌス帝)と国教化(392年・テオドシウス帝)を取りちがえる。「公認 → 正統の決定(325年)→ 国教化」の順で、皇帝名とセットにする。', '紀元前の年代を並べるとき、数字が小さいほうを古いと考えてしまう。紀元前は数字が大きいほど古い。前287年は前264年より古い。'],
    sum: ['メソポタミアは開放的な地形で興亡が激しく、エジプトは閉鎖的な地形で王国が長続きした。', 'オリエントはアッシリア(力の支配)→ 4王国 → アケメネス朝(寛容な支配)と統一された。', 'ギリシアでは重装歩兵・無産市民と戦う人が広がるにつれて民主政が発展し、ペリクレスの時代に完成した。', 'アレクサンドロス大王の東方遠征でヘレニズム文化が生まれた。', 'ローマは身分闘争で平等を進めたが、拡大による中小農民の没落から内乱となり、アウグストゥスの元首政で帝政に移った。', 'キリスト教は迫害のあと公認(313年)・国教化(392年)され、帝国は395年に東西に分裂した。'],
    next: '次は「古代のインドと中国(wh_asia_old)」に進みましょう。同じころ、アジアでもインダス文明から仏教の誕生、殷・周から秦・漢の大帝国へと、別の大きな流れが進んでいました。ヘレニズムがインドのガンダーラ美術に影響したように、東西のつながりにも注目します。'
  };

  // ===== 古代のインドと中国 =====
  L.wh_asia_old = {
    goal: 'インダス文明からグプタ朝までのインドの宗教と王朝の流れ、殷・周から秦・漢までの中国の支配のしくみと思想(諸子百家)を、つながりのある流れとして説明できるようになる。',
    intro: '日本の文化には、インドと中国から伝わったものがたくさんあります。お寺の仏教はインドで生まれ、中国を通って日本に来ました。漢字も、もとは殷の時代に占いに使われた甲骨文字です。「仁」「礼」を重んじる考え方は、孔子の儒学から来ています。\nこの単元では、インドと中国という2つの大きな文明が、それぞれどのように宗教や思想を生み、大帝国をつくったのかを学びます。インドは【宗教と身分のしくみ】、中国は【地方をどう治めるか(支配のしくみ)】に注目すると、流れがすっきり見えてきます。',
    pre: 'インドと中国の文明も、大きな川の流域で生まれました。インドは【インダス川】と、のちに中心となる【ガンジス川】、中国は【黄河】と【長江】です。\nアジアの南部・東部には、夏と冬で風向きが変わる【季節風(モンスーン)】がふき、夏に多くの雨をもたらします。この雨が稲作をささえました。季節風は、のちにインド洋の航海にも利用されます。\n中国の歴史では、王朝が次々と入れかわります。古代の中国では、徳を失った君主は天から見放され、別の家系に天命が移ると考えられました。これを【易姓革命】といいます。王朝の交代を正しいことと説明するための考え方です。\n【諸侯】とは、王から土地を与えられ、その地域を治める有力者のことです。【官吏】は、君主に任命されて政治の仕事をする役人で、世襲ではありません。この2つのちがいが、この単元の中国史のカギになります。\n前の単元で学んだヘレニズム文化が、インドにも影響を与えたことを思い出しておきましょう。',
    secs: [
      { h: 'インダス文明とアーリヤ人:身分のしくみの始まり', t: '前2600年ごろ、インダス川の流域に【インダス文明】が栄えました。代表的な遺跡の【モエンジョ=ダーロ】や【ハラッパー】は、焼きれんがでつくられた計画都市で、道路が碁盤の目のように整い、排水溝や大浴場もありました。\n人々は動物などを刻んだ印章を使い、そこに記された【インダス文字】は、今もまだ解読されていません。インダス文明は前1800年ごろまでに衰えましたが、その理由ははっきり分かっていません。\n前1500年ごろ、中央アジアから【アーリヤ人】がインド北西部のパンジャーブ地方に進入しました。アーリヤ人は自然の神々をたたえる讃歌を残し、その最古のものが『リグ=ヴェーダ』です。こうした聖典をもとにした宗教を【バラモン教】といいます。\nアーリヤ人は、前1000年ごろからガンジス川流域に移り、鉄器を使って農業を広げました。その中で、【ヴァルナ制】という身分のしくみがつくられました。ヴァルナは、司祭の【バラモン】、王侯・戦士の【クシャトリヤ】、農民・牧畜民・商人の【ヴァイシャ】、隷属民の【シュードラ】の4つです。その外側には、さらに差別された人々がおかれました。\nその後、ヴァルナ制は、生まれた家の職業などで決まる多くの集団(【ジャーティ】)と結びつき、長い時間をかけて、のちに【カースト制度】とよばれる社会のしくみになりました。結婚や食事の相手も同じ集団の中で決めるという、強いきまりをもっていました。',
        key: 'インダス文明は計画都市・インダス文字(未解読)。アーリヤ人のヴェーダとバラモン教、ヴァルナ制(バラモン・クシャトリヤ・ヴァイシャ・シュードラ)がジャーティと結びついてカースト制度へ。' },
      { h: '新しい宗教と、インドの統一王朝', t: 'なぜ前6世紀ごろのインドで新しい宗教が生まれたのでしょうか。ガンジス川流域では都市国家が成長し、商業が発達して、クシャトリヤやヴァイシャが力をつけていました。かれらは、祭式を独占して最上位にいるバラモンに反発しました。\nバラモン教の中でも、形式的な祭式より内面の思索を重んじる【ウパニシャッド哲学】が生まれました。そして前6〜前5世紀ごろ、【ガウタマ=シッダールタ(ブッダ)】が【仏教】を開きました。仏教は、ヴァルナの区別を否定し、正しい修行によって苦しみから解放される(解脱)ことを説いたため、クシャトリヤやヴァイシャに支持されました。同じころ、ヴァルダマーナは、きびしい苦行と不殺生を説く【ジャイナ教】を開き、商人に広まりました。\n前4世紀末、チャンドラグプタが【マウリヤ朝】をおこし、インド最初の統一王朝をつくりました。前3世紀の【アショーカ王】は、征服戦争の悲惨さを反省して仏教に帰依し、【ダルマ(法)】にもとづく政治を行いました。その内容を詔勅として磨崖や石柱に刻ませ、仏典の結集(編集)を行い、スリランカへも布教しました。\n1世紀には、中央アジアから進んだイラン系の【クシャーナ朝】が北インドを支配しました。2世紀ごろのカニシカ王は仏教を保護しました。このころ、出家した人だけでなく、多くの人々の救済をめざす【大乗仏教】が広まりました。また、ヘレニズム文化の影響を受けて、ギリシア彫刻のような仏像がつくられました。これを【ガンダーラ美術】といいます。\n4世紀には、チャンドラグプタ1世が【グプタ朝】をおこしました。グプタ朝のころ、バラモン教に民間の信仰が取りこまれた【ヒンドゥー教】が社会に定着し、人々の生活のきまりを定めた『マヌ法典』がまとめられました。サンスクリット語の文学が栄え、カーリダーサが戯曲『シャクンタラー』を書きました。数学では【ゼロの概念】が生まれ、のちにイスラーム世界を通じてヨーロッパに伝わります。美術では、純インド的なグプタ様式が完成し、アジャンター石窟寺院の壁画が知られています。チャンドラグプタ2世の時代には、中国(東晋)の僧【法顕】が仏典を求めて訪れました。',
        key: 'マウリヤ朝=アショーカ王のダルマ政治と仏教保護。クシャーナ朝=カニシカ王・大乗仏教・ガンダーラ美術。グプタ朝=ヒンドゥー教の定着・サンスクリット文学・ゼロの概念。',
        flow: { title: '古代インドの流れ(上から下へ)', cols: 2, head: ['王朝・社会', '宗教・文化'], rows: [
          [['インダス文明', 'g', 1, '前2600年ごろ〜'], ['印章・インダス文字', 'k', 1, '未解読']],
          [['アーリヤ人の進入', 'g', 1, '前1500年ごろ・ヴァルナ制'], ['バラモン教', 'k', 1, 'ヴェーダ']],
          [['都市国家の成長', 'g', 1, 'クシャトリヤ・ヴァイシャの台頭'], ['仏教・ジャイナ教', 'o', 1, '前6〜前5世紀ごろ']],
          [['マウリヤ朝', 'g', 1, '前4世紀末〜・アショーカ王'], ['仏教の保護', 'o', 1, 'ダルマの政治']],
          [['クシャーナ朝', 'g', 1, '1世紀〜・カニシカ王'], ['大乗仏教・ガンダーラ美術', 'o', 1, 'ヘレニズムの影響']],
          [['グプタ朝', 'g', 1, '4世紀〜'], ['ヒンドゥー教の定着', 'r', 1, 'サンスクリット文学・ゼロ']]
        ], legend: [['g', '王朝・社会'], ['k', 'バラモン教の時代'], ['o', '仏教'], ['r', 'ヒンドゥー教']] },
        ex: [{ q: '仏教がクシャトリヤやヴァイシャに支持されたのはなぜか。説明しよう。', hint: '当時、最上位のヴァルナはだれで、仏教はヴァルナをどう考えたかに注目しましょう。', steps: ['当時、バラモンが祭式を独占し、ヴァルナ制の最上位にいた。', '都市や商業の発達で、王侯・戦士のクシャトリヤや商人のヴァイシャが力をつけ、バラモンの権威に反発していた。', '仏教は、ヴァルナの区別を否定し、生まれではなく修行によって救われると説いた。', 'そのため、バラモン中心の秩序に不満をもつクシャトリヤやヴァイシャに受け入れられた。'], a: '力をつけたクシャトリヤやヴァイシャはバラモンの権威に反発しており、仏教がヴァルナの区別を否定して、生まれにかかわらず修行で救われると説いたから。', check: '「支持した人々の不満」と「仏教の教えの内容」の両方が、答えに入っているかを確かめます。' }] },
      { h: '殷と周:神の政治から血縁の政治へ', t: '中国では、黄河の中・下流域で農耕文化が発達し、前16世紀ごろには、現在確認できる最古の王朝【殷】が成立しました。殷の都の遺跡(殷墟)からは、多くの青銅器と【甲骨文字】が見つかっています。\n殷の王は、亀の甲や牛の骨を焼いてできたひびで神意を占い、その結果をもとに政治を行いました。これを【神権政治】といいます。甲骨文字は、その占いの内容を刻んだ文字で、漢字のもとになりました。\n前11世紀ごろ、渭水流域からおこった【周】が殷を倒し、鎬京(現在の西安の近く)を都としました。周は、広い地域を治めるために【封建制】をとりました。王は一族や功臣に土地(封土)を与えて【諸侯】とし、諸侯は王に貢ぎ物と軍役で奉仕しました。諸侯の地位は世襲されました。\n周の封建制をささえたのは【血縁】の結びつきでした。同じ祖先をもつ一族(宗族)の中で、本家と分家の秩序を守るきまり(宗法)があり、王と諸侯の関係も、一族の秩序と重なっていました。\n前770年、周は都を東の洛邑に移しました。これ以降を東周といい、前半を【春秋時代】、前403年以降を【戦国時代】といいます。春秋時代には、有力な諸侯(覇者)が「尊王攘夷」をかかげて他の諸侯をまとめましたが、戦国時代になると、諸侯は自ら「王」と名のり、「戦国の七雄」とよばれる7つの強国が争いました。\nこの時代には、【鉄製農具】と【牛耕】が広まって農業生産が増え、商業もさかんになって青銅の貨幣が使われました。実力で争う時代になると、血縁よりも能力を重んじて人材を集める国が強くなり、さまざまな思想家が各国に招かれました。',
        key: '殷=甲骨文字の神権政治。周=血縁にもとづく封建制(諸侯は世襲)。前770年の遷都で春秋時代、前403年から戦国時代。鉄製農具と牛耕で社会が変わった。' },
      { h: '諸子百家:乱世をどう治めるか', t: '春秋・戦国時代は、周の秩序がくずれ、諸侯が争う乱世でした。各国は国を強くするための知恵を求め、さまざまな思想家が生まれました。これを【諸子百家】といいます。どの思想も「どうすれば世の中がうまく治まるか」という同じ問いに答えようとしたものです。\n【儒家】の【孔子】(春秋時代)は、家族の中での親愛の情を社会に広げる【仁】と、それを形に表す【礼】を重んじ、徳による政治(徳治主義)を説きました。その言行は弟子によって『論語』にまとめられました。\n戦国時代の【孟子】は、人の本性は善であるとする【性善説】を説き、徳による王道政治を主張しました。徳を失った君主は倒されてもよいという易姓革命の考えも説きました。一方、【荀子】は、人の本性は悪であるとする【性悪説】を説き、【礼】によって人を正しく導くことを重んじました。\n【道家】の【老子】と【荘子】は、人為をすてて自然のままに生きる【無為自然】を説きました。儒家の仁や礼は、かえって人をしばる人為だと批判したのです。\n【墨家】の【墨子】は、儒家の仁は身内を中心にした差別的な愛だと批判し、へだてのない愛である【兼愛】と、侵略戦争を否定する【非攻】を説きました。\n【法家】は、道徳ではなく、きびしい【法】と賞罰によって国を治めることを主張しました。秦の【商鞅】は法家の考えで改革を行い、秦を強国にしました。荀子に学んだ【韓非】は法家の思想を大成しました。法家の考えは、のちに秦の中国統一をささえることになります。\nこのほか、外交策を説いた縦横家(蘇秦・張儀)、戦術を論じた兵家(孫子)、自然現象と社会を結びつけた陰陽家などもいました。',
        key: '儒家(孔子=仁と礼、孟子=性善説、荀子=性悪説)・道家(老子・荘子=無為自然)・墨家(墨子=兼愛・非攻)・法家(商鞅・韓非=法による統治)。',
        ex: [{ q: '次の主張は、諸子百家のどの学派のものか答えよう。「人の本性は悪であるから、礼によって正しく導かなければならない。」', hint: '性善説と性悪説、どちらにあたるかを考えましょう。', steps: ['「人の本性は悪」とあるので、性悪説の主張である。', '性悪説を説いたのは、戦国時代の儒家の荀子。', '「礼によって導く」は、礼を重んじる儒家の考え方と合う。', '法家の韓非は荀子に学んだが、礼ではなく法と賞罰による統治を説いたので、ここでは当てはまらない。'], a: '儒家(荀子)', check: '「性悪説」だけで法家と答えないように、「礼」か「法」かを確かめて区別します。' }] },
      { h: '秦と漢:皇帝が官吏を通じて治める帝国', t: '戦国時代の秦は、商鞅の改革で強国となり、前221年に【秦王政】が中国を統一しました。政は、それまでの「王」より上の称号として【皇帝】を名のり、【始皇帝】とよばれます。\n始皇帝は、周の封建制をやめ、全国に【郡県制】をしきました。郡県制では、地方を郡と県に分け、中央から皇帝が任命した【官吏】を送って治めさせます。世襲の諸侯がいないので、皇帝の力が地方のすみずみまで届きます。さらに、度量衡(長さ・容積・重さの単位)、文字、貨幣(半両銭)を統一し、法家の考えにもとづいて思想を統制する【焚書・坑儒】を行いました。北方の遊牧民【匈奴】に対しては、【万里の長城】を修築しました。\nしかし、急激な改革と、長城や宮殿の建設のための重い負担に人々は苦しみました。始皇帝の死後、前209年に農民の【陳勝・呉広の乱】が起こり、秦はわずか15年ほどで滅びました。\n農民出身の【劉邦】は、項羽との争いに勝って、前202年に【漢】(前漢)を建て、長安を都としました。劉邦(高祖)は、秦の急激な郡県制が反発をまねいたことから、都の周辺は郡県制、地方は一族や功臣を王とする封建制という【郡国制】をとりました。その後、諸侯王の勢力をおさえる政策が進み、前154年の呉楚七国の乱を経て、実質的には郡県制と同じになりました。\n前漢の最盛期の【武帝】(前2世紀後半)は、匈奴を攻撃し、匈奴をはさみ撃ちにするため大月氏へ【張騫】を派遣しました。張騫の旅で、西方の事情が中国に知られるようになりました。武帝はまた、朝鮮に【楽浪郡】などをおき、南の南越を征服しました。度重なる遠征で財政が苦しくなると、【塩・鉄の専売】や、物価の調整をはかる均輸・平準を行いました。思想では、董仲舒の意見で【儒学を官学】とし、儒学が国の教えとなりました。\n前漢は、外戚の王莽に皇帝の位をうばわれ、新(8〜23年)にかわりました。その後、一族の劉秀(光武帝)が25年に漢を復興し、洛陽を都としました。これを【後漢】といいます。57年には、倭の奴国の使いに光武帝が印綬を与えたことが記録されています。後漢では、宦官と官僚の争いや豪族の成長で政治が乱れ、184年の【黄巾の乱】をきっかけに混乱し、220年に滅びました。',
        key: '周=封建制(世襲の諸侯)→ 秦=郡県制(任命された官吏)→ 前漢=郡国制(ゆるやかな両者の組み合わせ)。武帝は匈奴攻撃・張騫派遣・塩鉄専売・儒学の官学化。',
        chain: { title: '秦の統一から漢の成立へ', items: [
          ['できごと', '秦王政が中国を統一(前221年)し、始皇帝となる', '郡県制・度量衡や文字・貨幣の統一'],
          ['原因', '急激な改革と重い負担', '焚書・坑儒、長城・宮殿の建設'],
          ['できごと', '陳勝・呉広の乱(前209年)', '各地で反乱が広がり、秦が滅びる'],
          ['結果', '劉邦が漢を建てる(前202年)', '秦の失敗を反省して郡国制をとる'],
          ['その後', '武帝の時代に最盛期', '儒学の官学化 → 中国の帝国の基本形']] } },
      { h: 'もっと深く:「封建制」は中国とヨーロッパで同じか', t: '「封建制」ということばは、中国の周の制度にも、中世ヨーロッパの制度にも使われます。どちらも「君主が家臣に土地を与え、家臣が奉仕する」という点では似ていますが、しくみの土台がちがいます。\n周の封建制の土台は【血縁】でした。王は、主に自分の一族を諸侯にし、宗法という一族のきまりで上下の秩序を守りました。つまり、政治の主従関係と家族の本家・分家の関係が重なっていたのです。\nこれに対して、中世ヨーロッパの封建制の土台は【契約】でした。主君と家臣は血縁がなくてもよく、主君は封土を与えて保護し、家臣は軍役で奉仕するという、おたがいに義務を負う(双務的な)契約で結ばれました。家臣は複数の主君をもつこともできました。\nもう一つのちがいは、その後の展開です。中国では、秦が早くも前221年に郡県制を全国に広め、漢以後も、皇帝が任命した官吏が地方を治める【中央集権】の帝国が、長く中国の基本の形になりました。ヨーロッパでは封建社会が長く続き、国王が官僚と常備軍をもって国全体を治めるようになるのは、中世の終わりから近世にかけてです。\nこのように、同じことばで表されていても、中身を比べると地域のちがいが見えてきます。比べるときは「何によって結ばれていたか(血縁か契約か)」「その後、中央集権化はいつ進んだか」の2つの観点を使いましょう。',
        key: '周の封建制=血縁(宗法)が土台。中世ヨーロッパの封建制=双務的な契約が土台。中国は秦・漢で早くから中央集権化した。' },
      { h: '入試ではこう出る:王朝と政策の組み合わせ・文化の対応', t: 'この分野の入試では、【王朝と人物・政策の組み合わせ】がもっともよく問われます。たとえば「アショーカ王=マウリヤ朝」「カニシカ王=クシャーナ朝」「法顕=グプタ朝(チャンドラグプタ2世)」「焚書・坑儒=秦」「張騫の派遣=前漢の武帝」などです。\n正誤問題のひっかけは、【時代が1つずれている】ものが多いです。たとえば「マウリヤ朝のもとでガンダーラ美術が栄えた」(正しくはクシャーナ朝)、「武帝が焚書・坑儒を行った」(正しくは秦の始皇帝)、「グプタ朝で仏教が国教になった」(グプタ朝ではヒンドゥー教が定着)などです。\n文化の問題では、【宗教と美術の対応】が問われます。ギリシア風の仏像=ガンダーラ美術(クシャーナ朝)、純インド的な様式=グプタ様式、アジャンター石窟寺院=グプタ様式、という対応をおさえましょう。\n論述では、「秦の郡県制と周の封建制のちがい」「仏教が支持された理由」「秦が短期間で滅びた理由」が定番です。いずれも、【だれが地方を治めるか】【だれが支持したか】【だれが負担に苦しんだか】と、人に注目して書くと答案がまとまります。',
        key: '王朝と人物・政策の組み合わせを1セットで覚える。ひっかけは「時代が1つずれている」もの。',
        ex: [
          { q: '次の文の正誤を判断し、誤りがあれば正しく直そう。「マウリヤ朝のカニシカ王は仏教を保護し、このころヘレニズムの影響を受けたガンダーラ美術が栄えた。」', hint: 'カニシカ王はどの王朝の王でしょうか。', steps: ['カニシカ王は、2世紀ごろのクシャーナ朝の王である。', 'マウリヤ朝で仏教を保護したのはアショーカ王。', 'ガンダーラ美術が栄えたのは、クシャーナ朝のころである。', 'したがって「マウリヤ朝」の部分が誤りで、「クシャーナ朝」に直す。'], a: '誤り。「マウリヤ朝」ではなく「クシャーナ朝」が正しい。', check: '人物 → 王朝 → 文化の3つが、すべて同じ時代にそろっているかを確かめます。' },
          { q: '秦が統一からわずか15年ほどで滅びた理由を、2つの観点から説明しよう。', hint: '「改革の進め方」と「人々の負担」の2つの観点で考えましょう。', steps: ['改革の進め方:周の封建制を一気にやめて郡県制を全国にしき、焚書・坑儒など法家によるきびしい統制を行った。', 'その結果、旧来の諸侯の勢力や学者などの反発をまねいた。', '人々の負担:万里の長城や宮殿・陵墓の建設に多くの人々が動員され、重い負担に苦しんだ。', '始皇帝の死後、陳勝・呉広の乱をきっかけに反乱が広がり、秦は滅びた。'], a: '郡県制の全国施行や焚書・坑儒など、急激できびしい改革が反発をまねき、さらに長城や宮殿の建設のための重い負担に人々が苦しんだため、始皇帝の死後に陳勝・呉広の乱をきっかけとする反乱が広がったから。', check: '理由が2つの観点に分かれて書かれ、最後に「陳勝・呉広の乱」という具体的なきっかけにつながっているかを確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: 'ヴァルナ制の4つの身分を、上から順に答えよう。', a: 'バラモン(司祭)・クシャトリヤ(王侯・戦士)・ヴァイシャ(農民・牧畜民・商人)・シュードラ(隷属民)', exp: 'ヴァルナ制は、アーリヤ人がガンジス川流域に進出したころに形づくられた身分のしくみです。\n最上位のバラモンは祭式を独占しました。仏教やジャイナ教は、このバラモンの権威に反発したクシャトリヤ・ヴァイシャに支持されたことと結びつけて覚えましょう。' },
      { lv: 1, q: '「無為自然」を説いた学派と、その代表的な思想家を答えよう。', a: '道家。老子・荘子。', exp: '道家は、人間の作った仁や礼などのきまり(人為)をすてて、自然のままに生きることを説きました。\n儒家の「仁・礼」を批判した学派としては、道家のほかに墨家(身内中心の愛を批判して兼愛を説く)があります。批判の向きがちがうので区別しましょう。' },
      { lv: 2, q: '周の封建制と秦の郡県制のちがいを、地方を治める人に注目して説明しよう。', a: '周の封建制では、王が一族や功臣に土地を与えて諸侯とし、諸侯が世襲で地方を治めた。秦の郡県制では、皇帝が任命した官吏を中央から派遣して地方を治めさせた。', exp: '封建制では地方の支配者(諸侯)の地位が世襲されるため、時がたつと王の力が届きにくくなります。実際、周の力が弱まると諸侯が争う春秋・戦国時代になりました。\n郡県制では、官吏は皇帝に任命され、世襲ではないので、皇帝が地方まで直接支配できます。\nこの「世襲の諸侯か、任命された官吏か」というちがいは、中世ヨーロッパや日本の歴史を比べるときにも役立つ見方です。' },
      { lv: 2, q: '前漢の武帝が塩・鉄の専売を始めた理由を説明しよう。', a: '匈奴への攻撃や朝鮮・南越への遠征などで財政が苦しくなったため、生活に欠かせない塩と鉄を国が独占して売り、収入を増やそうとしたから。', exp: '塩と鉄は、だれもが必要とする生活必需品です。国がその販売を独占すれば、確実に大きな収入が得られます。\n武帝は、塩・鉄の専売とあわせて、物資の輸送と物価の調整をはかる均輸・平準も行いました。\n「積極的な対外政策 → 財政難 → 専売などの財政政策」という因果の流れで覚えておきましょう。' },
      { lv: 3, q: 'グプタ朝の時代の文化の特色を、それ以前の時代と比べて70字程度で説明しよう。(記述)', a: '(模範解答)それまで仏教が保護され、ガンダーラ美術などヘレニズムの影響を受けた文化も栄えたが、グプタ朝ではヒンドゥー教が定着し、サンスクリット文学やグプタ様式などインド独自の文化が完成した。(88字)', exp: 'マウリヤ朝やクシャーナ朝では仏教が保護され、クシャーナ朝ではギリシア風の仏像(ガンダーラ美術)が生まれました。\nグプタ朝では、バラモン教に民間信仰が取り入れられたヒンドゥー教が社会に定着し、宮廷ではサンスクリット語が公用語のように使われて、カーリダーサの『シャクンタラー』などの文学が栄えました。美術でも、純インド的なグプタ様式が完成しました。\n採点のポイントは、(1)以前は仏教の保護や外来(ヘレニズム)の影響、(2)グプタ朝ではヒンドゥー教の定着、(3)サンスクリット文学やグプタ様式などインド的な文化の完成、の3点です。字数が多少前後しても、この3要素がそろっていれば高い評価になります。' },
      { lv: 3, q: '前漢の初めに郡国制がとられた理由を、秦の統治と関連づけて説明しよう。(記述)', a: '(模範解答)秦は郡県制を全国に一気に広めたことで反発をまねき、短期間で滅んだ。そこで高祖(劉邦)は、都の周辺は郡県制で直接治め、地方には一族や功臣を王として封じる封建制を残し、急激な中央集権による反発を避けようとしたから。', exp: '郡国制は、郡県制と封建制を組み合わせた制度です。なぜ「組み合わせ」にしたのかを、秦の失敗から説明するのがこの問題のねらいです。\n秦の郡県制は皇帝の力を強めましたが、それまでの諸侯の伝統を一気になくしたことや、厳しい法による統治が反発をまねきました。高祖は、この教訓から、ゆるやかなしくみで国をまとめようとしました。\nその後、諸侯王の力が強くなりすぎたため、前154年の呉楚七国の乱を経て、漢は諸侯王の権限をうばい、実質的に郡県制と同じ体制になりました。\n採点のポイントは、(1)秦の郡県制が反発をまねいて短期間で滅んだこと、(2)郡国制が郡県制と封建制の組み合わせであること、(3)急激な中央集権を避けたという目的、の3点です。' }
    ],
    faq: [
      ['ヒンドゥー教と仏教は、どちらが古いの?', '仏教のほうが先に「一つの宗教」としてまとまりました。仏教は前6〜前5世紀ごろに開かれましたが、【ヒンドゥー教】は、もっと古いバラモン教に民間の信仰が長い時間をかけて取り入れられてできた宗教で、グプタ朝のころに社会に定着しました。\nつまり、ヒンドゥー教のもと(バラモン教)は仏教より古く、ヒンドゥー教として定着したのは仏教の誕生よりあとです。'],
      ['儒学はいつから中国の「国の教え」になったの?', '前漢の【武帝】のとき、董仲舒の意見で儒学が官学とされたのが始まりです。秦では法家が重んじられ、儒学は焚書・坑儒で弾圧されていました。\nその後、儒学は中国の王朝の政治と教育の中心になり、朝鮮・日本など東アジアにも広まりました。'],
      ['「秦」と「清」は同じ国?', 'ちがいます。【秦】は前221年に中国を統一した王朝(始皇帝)で、【清】は17世紀から20世紀初めまで続いた中国最後の王朝です。読みは同じ「しん」でも、時代が約1800年もちがいます。\n答案では漢字をまちがえないように注意しましょう。']
    ],
    terms: [['ヴァルナ制', 'アーリヤ人がつくった、バラモン・クシャトリヤ・ヴァイシャ・シュードラの4つの身分のしくみ'], ['ジャーティ', '生まれた家の職業などで決まる多くの集団。ヴァルナと結びついてカースト制度となった'], ['ダルマ', '「法」の意味。アショーカ王は、ダルマにもとづく政治を行った'], ['大乗仏教', '出家者だけでなく、多くの人々の救済をめざす仏教'], ['封建制(周)', '王が一族や功臣に土地を与えて諸侯とし、世襲で治めさせる制度。血縁が土台'], ['郡県制', '地方を郡と県に分け、皇帝が任命した官吏に治めさせる制度'], ['郡国制', '前漢が採用した、都の周辺は郡県制、地方は封建制とする制度'], ['諸子百家', '春秋・戦国時代に現れた、さまざまな思想家とその学派']],
    miss: ['アショーカ王とカニシカ王の王朝を取りちがえる。アショーカ王=マウリヤ朝(前3世紀)、カニシカ王=クシャーナ朝(2世紀ごろ)。「ア→カ」と時代順に並べて覚える。', 'ガンダーラ美術をグプタ朝の美術と思う。ガンダーラ美術はクシャーナ朝のころのヘレニズムの影響を受けた仏教美術。グプタ朝はインド独自のグプタ様式。', '性善説を荀子、性悪説を孟子と逆に覚える。孟子=性善説で「王道」、荀子=性悪説で「礼」。孟子の「も」と「もともと善」をつなげて覚える。', '焚書・坑儒を漢の武帝の政策と思う。焚書・坑儒は秦の始皇帝。武帝はむしろ儒学を官学にした。儒学に対する態度が正反対であることで区別する。', '郡国制を「郡県制より中央集権的な制度」と思う。郡国制は郡県制と封建制の組み合わせで、秦よりもゆるやかなしくみ。'],
    sum: ['インダス文明のあと、アーリヤ人がヴァルナ制とバラモン教をつくり、のちにカースト制度へとつながった。', '仏教・ジャイナ教はバラモンに反発するクシャトリヤ・ヴァイシャに支持された。', 'マウリヤ朝(アショーカ王)・クシャーナ朝(カニシカ王)は仏教を保護し、グプタ朝ではヒンドゥー教が定着した。', '殷は神権政治、周は血縁にもとづく封建制。春秋・戦国の乱世に諸子百家が生まれた。', '秦は郡県制で中央集権を進めたが短期間で滅び、漢は郡国制から始めて武帝のときに最盛期をむかえた。'],
    next: '次は「イスラーム世界の成立と発展(wh_islam)」に進みましょう。グプタ朝で生まれたゼロの概念が、イスラーム世界を通じて広まったように、7世紀以降は西アジアのイスラーム世界が、東西の文化をつなぐ中心になります。'
  };

  // ===== イスラーム世界の成立と発展 =====
  L.wh_islam = {
    goal: 'ムハンマドによるイスラーム教の成立から、正統カリフ・ウマイヤ朝・アッバース朝をへてイスラーム世界が分かれていく流れと、イスラーム文化の特色を、税制や宗派のちがいもふくめて説明できるようになる。',
    intro: 'ふだん使っている「1、2、3」の数字は「アラビア数字」とよばれます。でも、もとはインドで生まれた数字で、それをイスラーム世界の人々が受けつぎ、ヨーロッパに伝えました。「アルコール」「アルカリ」「シュガー(砂糖)」などのことばも、アラビア語から来ています。\n7世紀にアラビア半島で生まれたイスラーム教は、約100年のうちに、西はイベリア半島から東は中央アジアまで広がりました。この単元では、【なぜそんなに早く広がったのか】【アラブ人の国が、どのようにすべてのムスリムの国へ変わったのか】を、税のしくみに注目して読み解きます。',
    pre: 'アラビア半島は、大部分が砂漠で、ラクダを使って遊牧をする人々(ベドウィン)と、オアシスの町で商業をする人々がくらしていました。\n6世紀後半、西アジアでは【ビザンツ帝国】と、イランの【ササン朝ペルシア】が長く戦っていました。そのため、両国の境界を通る東西の交易路が危険になり、アラビア半島を通るルートが使われるようになりました。こうして、半島西部の【メッカ】は隊商貿易の中心として栄えました。\nしかし、商業で豊かになる人がいる一方で、貧富の差が広がり、部族の古いきまりもゆらいでいました。\n宗教の面では、前の単元で学んだ【ユダヤ教】と【キリスト教】という一神教が、すでにアラビア半島にも伝わっていました。イスラーム教は、この流れを受けついだ一神教です。\n用語として、【ムスリム】は「イスラーム教徒」、【カリフ】は「(預言者ムハンマドの)後継者」という意味です。',
    secs: [
      { h: 'ムハンマドとイスラーム教の成立', t: 'メッカの商人の家に生まれた【ムハンマド】は、610年ごろ、唯一神【アッラー】のことばを授かった預言者だと自覚し、教えを説き始めました。これが【イスラーム教】です。「イスラーム」とは、「(唯一の神に)絶対に従うこと」という意味です。\nムハンマドは、神の前ではすべての人が平等であると説き、偶像崇拝をきびしく禁じました。これは、多くの神々の像をまつるカーバ神殿への巡礼で利益を得ていたメッカの大商人たちにとって都合が悪く、ムハンマドは迫害されました。\n622年、ムハンマドは信者とともにメッカから【メディナ】へ移りました。これを【ヒジュラ(聖遷)】といいます。メディナでムハンマドは、部族のちがいをこえた信者の共同体【ウンマ】をつくりました。この年が、のちにイスラーム暦の元年とされました。信仰の共同体が生まれた、イスラームの歴史の出発点だからです。\nムハンマドは630年にメッカを征服し、カーバ神殿の偶像を破壊して、イスラーム教の聖殿としました。632年に亡くなるまでに、アラビア半島の多くの部族がイスラームに従いました。\nムハンマドに下された神のことばは、聖典【コーラン(クルアーン)】にまとめられました。コーランはアラビア語で書かれ、信仰だけでなく、結婚・相続・商売など生活のすべてにわたるきまりをふくみます。ムスリムが信じるべき6つのこと(神・天使・啓典・預言者・来世・天命)と、行うべき5つのこと(信仰告白・礼拝・喜捨・断食・巡礼)を、あわせて【六信五行】といいます。\nイスラーム教では、ムハンマドは「最後で最大の預言者」とされ、イエスもそれ以前の預言者の一人と位置づけられます。神と人のあいだに立つ聖職者はおらず、信者はコーランにもとづいて直接神に向き合います。',
        key: '610年ごろムハンマドが布教 → 622年ヒジュラ(イスラーム暦元年)・ウンマの成立 → 630年メッカ征服。聖典はコーラン、信仰と実践は六信五行。',
        ex: [{ q: 'ムハンマドがメッカの大商人たちから迫害されたのはなぜか。説明しよう。', hint: 'ムハンマドの教えと、メッカの大商人の利益の関係を考えましょう。', steps: ['ムハンマドは唯一神アッラーへの信仰を説き、偶像崇拝をきびしく禁じた。', '当時のメッカのカーバ神殿には多くの神々の像がまつられ、巡礼者が集まっていた。', '大商人たちは、この巡礼や交易から大きな利益を得ていた。', 'また、神の前の平等を説く教えは、富を独占する大商人の立場をおびやかすものだった。'], a: '偶像崇拝の否定は、カーバ神殿への巡礼で利益を得ていた大商人の利益をおびやかし、神の前の平等を説く教えも、貧富の差の上に立つ大商人の立場と対立したから。', check: '「教えの内容」と「大商人の利益」の両方が答えに入っているかを確かめます。' }] },
      { h: '正統カリフ時代とウマイヤ朝:アラブ人の大征服', t: 'ムハンマドの死後、信者たちは話し合いでアブー=バクルを後継者【カリフ】に選びました。第4代のアリーまで、選挙で選ばれたカリフが続いた時代を【正統カリフ時代】(632〜661年)といいます。\nこの時代、アラブ人のムスリムは「ジハード(聖戦)」として大規模な征服活動を行いました。長い戦争で疲れていたビザンツ帝国からシリア・エジプトをうばい、ササン朝ペルシアを642年のニハーヴァンドの戦いで破って、まもなく滅ぼしました。\nなぜこれほど早く征服が進んだのでしょうか。ビザンツとササン朝が長い戦争で弱っていたことに加え、征服されたキリスト教徒やユダヤ教徒など【啓典の民】は、税を払えば信仰を続けることを認められたからです。人々にとっては、それまでの重い支配よりも受け入れやすい面がありました。\n第4代カリフのアリーが暗殺されると、シリア総督の【ムアーウィヤ】が661年にカリフとなり、【ウマイヤ朝】を開きました。都は【ダマスクス】です。これ以降、カリフの地位はウマイヤ家に世襲されるようになりました。\nこのとき、アリーとその子孫だけを正しい指導者と考える人々は、ウマイヤ朝を認めませんでした。これが【シーア派】(「アリーの党派」の意味)です。これに対し、歴代のカリフを認め、ムハンマドの言行(スンナ)に従う多数派を【スンナ派】といいます。\nウマイヤ朝は、東は中央アジア・インド西部、西は北アフリカに広がり、711年にはイベリア半島の西ゴート王国を滅ぼしました。しかし、732年の【トゥール・ポワティエ間の戦い】で、フランク王国の宮宰カール=マルテルに敗れ、ガリア(今のフランス)への進出は止まりました。\nウマイヤ朝は、征服者である【アラブ人を優遇】する国でした。アラブ人は土地をもっても地租(ハラージュ)を払わず、一方で征服された人々は、イスラームに改宗しても人頭税(ジズヤ)と地租を払わされることがありました。このため、改宗した非アラブ人(マワーリー)の不満が高まりました。',
        key: '正統カリフ時代(632〜661年)に大征服。ウマイヤ朝(661年〜・ダマスクス)はカリフを世襲し、アラブ人を優遇した。アリーの子孫を正統とするのがシーア派、多数派はスンナ派。' },
      { h: 'アッバース朝:「イスラーム帝国」への変化', t: 'ウマイヤ朝のアラブ人優遇に不満をもつ人々や、シーア派の協力を得て、750年に【アッバース朝】が成立しました。2代カリフのマンスールは、新しい都【バグダード】を建設しました。\nアッバース朝の大きな変化は、【イスラーム法(シャリーア)のもとでのムスリムの平等】が実現したことです。アラブ人でもムスリムでなくても、土地をもつ者は地租(ハラージュ)を払い、ムスリムであれば人頭税(ジズヤ)は免除されました。つまり、税の区別の基準が「アラブ人かどうか」から「ムスリムかどうか」に変わったのです。\nこのため、アッバース朝は【アラブ帝国】から【イスラーム帝国】に変わったといわれます。官僚には改宗したイラン人なども多く登用され、ペルシアの行政のしくみが取り入れられました。\n成立の翌年の751年、アッバース朝は中央アジアの【タラス河畔の戦い】で唐の軍を破りました。このとき、捕虜となった唐の兵の中に紙すきの職人がいて、【製紙法】がイスラーム世界に伝わったとされています。\nアッバース朝は、8世紀後半から9世紀初めの【ハールーン=アッラシード】のころに最盛期をむかえました。バグダードは、陸と海の交易路が集まる国際都市として大いに栄えました。',
        key: 'アッバース朝(750年〜・バグダード)で、税の基準が「アラブ人か」から「ムスリムか」へ。アラブ帝国からイスラーム帝国へ変わった。751年タラス河畔の戦いで製紙法が伝わる。',
        flow: { title: 'ウマイヤ朝とアッバース朝の税のちがい', cols: 3, head: ['', 'ウマイヤ朝', 'アッバース朝'], rows: [
          [['アラブ人のムスリム', 'k'], ['ジズヤ:なし / ハラージュ:なし', 'r', 1, 'アラブ人の特権'], ['ジズヤ:なし / ハラージュ:土地があれば払う', 'gr', 1, '特権がなくなる']],
          [['改宗した非アラブ人(マワーリー)', 'k'], ['ジズヤ・ハラージュを払わされることがあった', 'o', 1, '不満が高まる'], ['ジズヤ:なし / ハラージュ:土地があれば払う', 'gr', 1, 'アラブ人と同じ']],
          [['異教徒(啓典の民など)', 'k'], ['ジズヤ・ハラージュを払う', 'b', 1, '信仰は認められる'], ['ジズヤ・ハラージュを払う', 'b', 1, '信仰は認められる']]
        ], legend: [['r', 'アラブ人の特権'], ['o', '不平等な負担'], ['gr', 'ムスリムの平等'], ['b', '異教徒の負担']] },
        ex: [{ q: 'アッバース朝が「イスラーム帝国」とよばれるのはなぜか。ウマイヤ朝と比べて説明しよう。', hint: '税をはらう・はらわないの基準が、何から何に変わったかを考えましょう。', steps: ['ウマイヤ朝では、征服者のアラブ人が優遇され、地租を払わなかった。', '一方、改宗した非アラブ人には、人頭税や地租が課されることがあった。', 'アッバース朝では、アラブ人でも土地をもてば地租を払い、ムスリムなら民族に関係なく人頭税が免除された。', 'つまり、特権の基準が「アラブ人であること」から「ムスリムであること」に変わった。'], a: 'ウマイヤ朝はアラブ人を優遇する「アラブ帝国」だったが、アッバース朝ではアラブ人の特権がなくなり、民族に関係なくムスリムが平等にあつかわれるようになったから。', check: '「ジズヤ」「ハラージュ」の2つの税について、だれが払うのかが答えに表れているかを確かめます。' }] },
      { h: 'イスラーム世界の分裂と、トルコ人・モンゴルの登場', t: 'アッバース朝の成立後、ウマイヤ家の一族はイベリア半島にのがれ、756年に【後ウマイヤ朝】を建てました。都は【コルドバ】です。こうして、イスラーム世界は一つの国ではなくなりました。\n909年には、シーア派の【ファーティマ朝】が北アフリカにおこり、のちにエジプトを征服して新しい都【カイロ】を建設しました。ファーティマ朝の君主は、アッバース朝のカリフを認めず、自らカリフを名のりました。これに対抗して、後ウマイヤ朝の君主もカリフを名のりました。10世紀には、【3人のカリフが並び立つ】状態になったのです。\nアッバース朝の内部でも、地方の総督が自立し、カリフの力は弱まりました。946年には、シーア派のイラン系軍事政権【ブワイフ朝】がバグダードに入り、カリフから大アミール(軍司令官)の地位を得て、実権をにぎりました。\n11世紀には、中央アジアからトルコ人の【セルジューク朝】が進出しました。1055年、トゥグリル=ベクはバグダードに入ってブワイフ朝を追い出し、アッバース朝のカリフから【スルタン】(支配者)の称号を受けました。カリフは宗教的な権威として残り、スルタンが政治と軍事の実権をにぎるという分担ができたのです。セルジューク朝はさらにアナトリアに進出してビザンツ帝国を圧迫し、これがヨーロッパの【十字軍】のきっかけとなりました。\n1258年、モンゴル帝国のフラグがバグダードを攻め落とし、アッバース朝は滅びました。フラグはイランを中心に【イル=ハン国】を建て、のちにイル=ハン国の君主はイスラームに改宗しました。\nこのとき、エジプトの【マムルーク朝】(1250〜1517年)はモンゴル軍の西進を食いとめ、カイロはイスラーム世界の新しい中心として栄えました。マムルークとは、トルコ人などの奴隷出身の軍人のことです。',
        key: '後ウマイヤ朝(756年・コルドバ)・ファーティマ朝(909年・のちカイロ)で3カリフが並立。ブワイフ朝(946年)→ セルジューク朝(1055年・スルタンの称号)→ 1258年モンゴルがアッバース朝を滅ぼす。',
        chain: { title: 'アッバース朝の動揺から滅亡へ', items: [
          ['分裂', '後ウマイヤ朝(756年)・ファーティマ朝(909年)が自立', '10世紀には3人のカリフが並び立つ'],
          ['動揺', 'ブワイフ朝がバグダードに入る(946年)', '大アミールとして実権をにぎる'],
          ['できごと', 'セルジューク朝がバグダードに入る(1055年)', 'カリフからスルタンの称号を受ける'],
          ['影響', 'セルジューク朝がビザンツ帝国を圧迫', 'ヨーロッパの十字軍のきっかけに'],
          ['結果', 'モンゴルのフラグがバグダードを攻略(1258年)', 'アッバース朝の滅亡・イル=ハン国の成立']] } },
      { h: 'イスラーム文化:固有の学問と外来の学問', t: 'イスラーム文化は、アラブ人のイスラーム教とアラビア語を中心に、征服した地域のギリシア・イラン・インドなどの文化が融合して生まれました。そのため、学問は【固有の学問】と【外来の学問】に分けて整理されます。\n【固有の学問】は、コーランとムハンマドの言行(ハディース)を研究するところから生まれた神学・法学・歴史学などです。イスラーム法を研究し、人々の生活を導く学者を【ウラマー】といいます。\n【外来の学問】は、哲学・医学・天文学・数学などです。アッバース朝のバグダードには「知恵の館(バイト=アルヒクマ)」がつくられ、ギリシア語の文献が大量にアラビア語に翻訳されました。とくにアリストテレスの哲学は深く研究されました。\n代表的な学者をおさえましょう。9世紀の【フワーリズミー】はインドから伝わった数字とゼロの考えを使って代数学を発展させました。11世紀の【イブン=シーナー】は『医学典範』を著し、12世紀のコルドバの【イブン=ルシュド】はアリストテレスの注釈を書きました。14世紀の【イブン=ハルドゥーン】は『世界史序説』で王朝の興亡の法則を論じ、同じく14世紀の旅行家【イブン=バットゥータ】は各地を旅して『三大陸周遊記』を残しました。\n信仰では、形式的な戒律の実践よりも、神との一体感を求める神秘主義【スーフィズム】が広まり、民衆のあいだにイスラームを広める大きな力になりました。文学では、さまざまな地域の説話を集めた『千夜一夜物語(アラビアン=ナイト)』が知られています。\n美術では、偶像崇拝を禁じたため、人物や動物ではなく、植物の文様や文字を組み合わせた【アラベスク】が発達しました。礼拝の場であるモスクには、礼拝の時刻を知らせる塔(ミナレット)が建てられました。\nイスラーム世界で受けつがれ発展したギリシアの学問は、12世紀ごろ、イベリア半島のトレドなどでアラビア語からラテン語に翻訳され、ヨーロッパに伝わりました。これがヨーロッパの学問の発展をうながし、のちのルネサンスの土台にもなりました。',
        key: '固有の学問(神学・法学など、担い手はウラマー)と外来の学問(ギリシアの哲学・医学など)。知恵の館で翻訳。イブン=シーナー・イブン=ルシュド・イブン=ハルドゥーン・イブン=バットゥータ。',
        ex: [{ q: '次の人物と著作・業績の組み合わせのうち、誤っているものを選ぼう。\nア イブン=シーナー ― 『医学典範』\nイ イブン=ハルドゥーン ― 『三大陸周遊記』\nウ フワーリズミー ― 代数学の発展\nエ イブン=ルシュド ― アリストテレスの注釈', hint: '「イブン=」で始まる4人を、医学・歴史・旅行・哲学に分けて整理しましょう。', steps: ['イブン=シーナーは医学者で、『医学典範』を著したのでアは正しい。', 'イブン=ハルドゥーンは歴史家で、著作は『世界史序説』。', '『三大陸周遊記』は旅行家イブン=バットゥータの旅行記なので、イは誤り。', 'フワーリズミーは代数学、イブン=ルシュドはアリストテレスの注釈で知られるので、ウ・エは正しい。'], a: 'イ(『三大陸周遊記』はイブン=バットゥータ。イブン=ハルドゥーンは『世界史序説』)', check: '医学=シーナー、歴史=ハルドゥーン、旅行=バットゥータ、哲学=ルシュド、と4つの分野に1人ずつ対応しているかを確かめます。' }] },
      { h: 'もっと深く:ムスリム商人とイスラームの広がり', t: 'イスラームは、征服によってだけ広まったのではありません。7〜8世紀の大征服のあと、イスラームが広がった大きな力は、【商業】と【スーフィー(神秘主義者)】の活動でした。\nイスラーム教は、ムハンマド自身が商人だったこともあり、正直な商売を重んじる宗教です。ムスリム商人は、陸ではラクダの隊商を組んでオアシスの道を進み、海ではダウ船とよばれる三角帆の船で、季節風を利用してインド洋を行き来しました。\n東アフリカの海岸では、ムスリム商人の来航によって、アラビア語の影響を受けた【スワヒリ語】が生まれ、マリンディやキルワなどの港町が栄えました。西アフリカでは、サハラ砂漠を越える塩と金の交易を通じてイスラームが広まりました。14世紀の【マリ王国】の王マンサ=ムーサは、大量の金を持ってメッカに巡礼したことで知られ、ニジェール川沿いのトンブクトゥはイスラームの学問の中心になりました。\n南アジアでは、13世紀初めの1206年、デリーを都とするイスラーム王朝(奴隷王朝)が成立し、以後のイスラーム王朝はまとめて【デリー=スルタン朝】とよばれます。東南アジアでは、13世紀末ごろから、ムスリム商人の活動を通じて港町の支配者が次々と改宗していきました。\nこのように、イスラームが広がった道すじは、ほとんどそのまま【交易のネットワーク】と重なります。共通の信仰、アラビア語、イスラーム法があることで、遠い土地の商人どうしでも安心して取り引きができたのです。宗教が「商売のルール」としても機能したことが、イスラーム世界の広がりを支えました。',
        key: 'イスラームは征服だけでなく、商業とスーフィーの活動で広がった。東アフリカのスワヒリ語、西アフリカのマリ王国、インドのデリー=スルタン朝、東南アジアの港町。' },
      { h: '入試ではこう出る:王朝・都・宗派の組み合わせと論述', t: 'イスラーム世界の入試問題では、【王朝 ― 都 ― 宗派 ― 民族】の組み合わせがくり返し問われます。ウマイヤ朝=ダマスクス=スンナ派=アラブ人、アッバース朝=バグダード、後ウマイヤ朝=コルドバ、ファーティマ朝=カイロ=シーア派、ブワイフ朝=シーア派=イラン系、セルジューク朝=スンナ派=トルコ系、というように、1つの王朝を4つの要素で表にしておきましょう。\n正誤問題では、【カリフとスルタンの区別】がねらわれます。カリフはムハンマドの後継者で、イスラーム共同体の指導者です。スルタンは、セルジューク朝のトゥグリル=ベクがアッバース朝のカリフから受けた、政治的な支配者の称号です。「セルジューク朝の君主がカリフを名のった」という文は誤りです。\n論述問題の定番は、「ウマイヤ朝とアッバース朝の統治のちがい」です。答案では、(1)ウマイヤ朝のアラブ人優遇、(2)改宗者(マワーリー)の不満、(3)アッバース朝でのムスリムの平等(税制の変化)、(4)「アラブ帝国からイスラーム帝国へ」というまとめ、の4つを入れると満点に近づきます。\nもう一つの定番は、「イスラーム文化がヨーロッパに与えた影響」です。ギリシアの古典がイスラーム世界で研究・発展し、12世紀にラテン語に翻訳されてヨーロッパに伝わった、という「逆輸入」の流れを書けるようにしましょう。',
        key: '王朝は「都・宗派・民族」とセットで表にする。カリフ(後継者)とスルタン(支配者の称号)を区別する。',
        ex: [
          { q: '次の文の正誤を判断し、誤りがあれば正しく直そう。「11世紀にバグダードに入ったセルジューク朝のトゥグリル=ベクは、自らカリフを名のった。」', hint: 'トゥグリル=ベクが受けた称号を思い出しましょう。', steps: ['トゥグリル=ベクは、1055年にバグダードに入り、ブワイフ朝を追い出した。', 'このとき、アッバース朝のカリフはそのまま残された。', 'トゥグリル=ベクは、カリフから「スルタン」の称号を受けた。', 'したがって「自らカリフを名のった」が誤り。'], a: '誤り。カリフを名のったのではなく、アッバース朝のカリフから「スルタン」の称号を受けた。', check: 'カリフを自ら名のった王朝(ファーティマ朝・後ウマイヤ朝)と、スルタンの称号を受けた王朝(セルジューク朝)を区別できているかを確かめます。' },
          { q: 'イスラーム教が7〜8世紀に短期間で広い地域に広がった理由を、征服された人々の立場から説明しよう。', hint: '征服された人々は、信仰を変えなければならなかったのでしょうか。', steps: ['当時、ビザンツ帝国とササン朝は長い戦争で弱り、その支配下の人々は重い負担に苦しんでいた。', 'ムスリムの軍は、征服したキリスト教徒やユダヤ教徒などの啓典の民に、税(ジズヤ・ハラージュ)を払えば信仰を続けることを認めた。', 'そのため、征服された人々にとって、新しい支配は必ずしも厳しいものではなかった。', '強制的に改宗させなかったことで大きな抵抗が起きにくく、支配が短期間で広がった。'], a: 'ビザンツ帝国やササン朝の支配に苦しんでいた人々に対して、ムスリムは税を払えば信仰を続けることを認めたため、征服された人々の抵抗が比較的小さく、支配が短期間で広がったから。', check: '「強制的に改宗させた」と書いていないかを確かめます。改宗の強制は、この時期の拡大の説明として誤りです。' }
        ] }
    ],
    drill: [
      { lv: 1, q: 'イスラーム教で、ムスリムが行うべき5つの行い(五行)をすべて答えよう。', a: '信仰告白・礼拝・喜捨・断食・巡礼', exp: '五行は、ムスリムが日々の生活の中で実践する義務です。礼拝は1日5回、メッカの方角に向かって行います。断食はイスラーム暦の第9月(ラマダーン)に、日の出から日没まで行います。巡礼はメッカへの巡礼(ハッジ)です。\n六信(神・天使・啓典・預言者・来世・天命)とあわせて「六信五行」と覚えましょう。' },
      { lv: 1, q: 'ウマイヤ朝・アッバース朝・後ウマイヤ朝・ファーティマ朝の都をそれぞれ答えよう。', a: 'ウマイヤ朝=ダマスクス、アッバース朝=バグダード、後ウマイヤ朝=コルドバ、ファーティマ朝=カイロ', exp: '都の位置は、王朝の性格と結びついています。ウマイヤ朝の都ダマスクスはシリア、アッバース朝のバグダードはイラク、後ウマイヤ朝のコルドバはイベリア半島、ファーティマ朝のカイロはエジプトにあります。\nファーティマ朝はカイロを建設した王朝で、のちのマムルーク朝の時代にもカイロはイスラーム世界の中心として栄えました。' },
      { lv: 2, q: 'ヒジュラの年がイスラーム暦の元年とされた理由を説明しよう。', a: 'メディナに移ったことで、部族をこえた信者の共同体(ウンマ)がはじめてつくられ、イスラーム教徒の社会が出発した年と考えられたから。', exp: 'ムハンマドが啓示を受けたのは610年ごろですが、暦の元年は622年のヒジュラです。\nこれは、イスラーム教にとって大切なのが個人の信仰だけでなく、信者が一つの共同体(ウンマ)をつくって生活することだからです。メディナで、はじめてイスラームの教えにもとづく共同体が成立しました。' },
      { lv: 2, q: 'シーア派とスンナ派が分かれたきっかけを、ウマイヤ朝の成立と関連づけて説明しよう。', a: '第4代カリフのアリーが暗殺され、ムアーウィヤがウマイヤ朝を開いてカリフの地位を世襲すると、アリーとその子孫だけを正統な指導者とする人々がシーア派となり、歴代カリフを認める多数派がスンナ派となった。', exp: 'シーア派とスンナ派の対立の根本は、「だれがイスラーム共同体の正しい指導者か」という問題です。\nシーア派は、ムハンマドのいとこで娘婿でもあるアリーの血筋を重んじます。スンナ派は、ムハンマドの言行(スンナ)に従い、共同体の合意で選ばれたカリフを認めます。\n現在でもスンナ派が多数派で、シーア派はイランなどに多くいます。' },
      { lv: 3, q: 'イスラーム世界がヨーロッパの学問の発展にはたした役割を、70字程度で説明しよう。(記述)', a: '(模範解答)イスラーム世界はギリシアの哲学や医学などをアラビア語に翻訳して研究・発展させ、それが12世紀ごろラテン語に翻訳されてヨーロッパに伝わり、学問の発展をうながした。(79字)', exp: 'アッバース朝のバグダードの「知恵の館」では、ギリシア語の文献がアラビア語に翻訳されました。イスラームの学者は、それをただ保存しただけでなく、イブン=シーナーの医学やイブン=ルシュドのアリストテレス研究のように、さらに発展させました。\n12世紀になると、イベリア半島のトレドなどで、これらのアラビア語の文献がラテン語に翻訳され、ヨーロッパに伝わりました(12世紀ルネサンス)。インド起源の数字やゼロの考えも、イスラーム世界を通じてヨーロッパに伝わりました。\n採点のポイントは、(1)ギリシアの学問をアラビア語に翻訳・研究したこと、(2)それを発展させたこと、(3)ラテン語に翻訳されヨーロッパに伝わったこと、の3点です。' },
      { lv: 3, q: '10世紀以降、アッバース朝のカリフの政治的な力が弱まった過程を、2つの王朝名を使って説明しよう。(記述)', a: '(模範解答)946年にイラン系のブワイフ朝がバグダードに入り、カリフから大アミールの地位を得て実権をにぎった。さらに1055年にトルコ系のセルジューク朝がバグダードに入り、カリフからスルタンの称号を受けて政治と軍事の実権をにぎったため、カリフは宗教的な権威にとどまった。', exp: 'アッバース朝のカリフは、滅ぼされたのではなく、軍事力をもつ新しい勢力に「実権をうばわれた」という点が大切です。\nブワイフ朝はシーア派でしたが、スンナ派のカリフを廃止せずに利用しました。セルジューク朝はスンナ派で、カリフの権威を守る立場からスルタンとして支配しました。\nこうして、カリフが宗教的な権威、スルタンが政治的な権力をになうという分担ができました。アッバース朝が実際に滅びたのは、1258年のモンゴル軍によるバグダード攻略のときです。\n採点のポイントは、(1)ブワイフ朝が大アミールとして実権をにぎったこと、(2)セルジューク朝がスルタンの称号を受けたこと、(3)カリフが宗教的な権威にとどまったこと、の3点です。' }
    ],
    faq: [
      ['カリフとスルタンは、どうちがうの?', '【カリフ】は「ムハンマドの後継者」という意味で、イスラーム共同体全体の指導者です。【スルタン】は「支配者・権力者」という意味で、セルジューク朝のトゥグリル=ベクが、アッバース朝のカリフから受けた称号として広まりました。\nカリフが宗教的な権威をもち、スルタンが政治・軍事の実権をもつという分担と考えると分かりやすいです。'],
      ['イスラーム教では、ほかの宗教の人はどうあつかわれたの?', 'キリスト教徒やユダヤ教徒は、神の啓示を記した聖典をもつ【啓典の民】とされ、人頭税(ジズヤ)を払えば信仰を続けることが認められました。\nもちろん、ムスリムと完全に同じ権利をもっていたわけではありませんが、改宗を強制しなかったことが、広い地域を治めるうえで大きな意味をもちました。'],
      ['「アラビア数字」は、アラビアで生まれたの?', 'いいえ。もとはインドで生まれた数字で、グプタ朝のころに【ゼロの概念】も生まれました。それがイスラーム世界に伝わり、フワーリズミーなどの学者が使って数学を発展させました。\nヨーロッパの人々は、イスラーム世界から伝わったので「アラビア数字」とよびました。']
    ],
    terms: [['ヒジュラ', '622年、ムハンマドがメッカからメディナへ移ったできごと。イスラーム暦の元年'], ['ウンマ', 'イスラーム教徒の共同体'], ['カリフ', 'ムハンマドの後継者。イスラーム共同体の指導者'], ['ジズヤ', '人頭税。アッバース朝ではムスリムは免除された'], ['ハラージュ', '地租。アッバース朝では、土地をもつ者はアラブ人でも払った'], ['シーア派', 'アリーとその子孫だけを正統な指導者とする宗派'], ['スルタン', 'セルジューク朝の君主がアッバース朝のカリフから受けた支配者の称号'], ['ウラマー', 'イスラーム法や神学を学んだ学者。人々の生活を導いた']],
    miss: ['ムハンマドの布教開始(610年ごろ)をイスラーム暦の元年と思う。元年は622年のヒジュラ。共同体(ウンマ)ができた年が出発点、と理由とセットで覚える。', 'ウマイヤ朝とアッバース朝の都を逆にする。ウマイヤ朝=ダマスクス(シリア)、アッバース朝=バグダード(イラク)。アッバース朝はバグダードを「新しく建設した」ことも覚える。', 'ウマイヤ朝でも「ムスリムは平等」だったと思う。ウマイヤ朝はアラブ人優遇。ムスリムの平等が実現したのはアッバース朝。', 'セルジューク朝の君主がカリフになったと思う。受けたのはスルタンの称号。カリフを自称したのは、ファーティマ朝と後ウマイヤ朝。', 'イスラームは剣による強制改宗で広まったと思いこむ。征服地では税を払えば信仰が認められ、のちには商業やスーフィーの活動が広まる大きな力になった。'],
    sum: ['610年ごろムハンマドが布教を始め、622年のヒジュラでウンマが生まれ、630年にメッカを征服した。', '正統カリフ時代に大征服が進み、ウマイヤ朝はカリフを世襲してアラブ人を優遇した。シーア派とスンナ派が分かれた。', 'アッバース朝ではムスリムが平等となり、「アラブ帝国からイスラーム帝国へ」変わった。', '10世紀に3カリフが並立し、ブワイフ朝・セルジューク朝が実権をにぎり、1258年にモンゴルがアッバース朝を滅ぼした。', 'イスラーム文化は固有の学問と外来の学問からなり、ギリシアの学問を発展させてヨーロッパに伝えた。', 'イスラームは商業とスーフィーの活動を通じて、アフリカ・南アジア・東南アジアに広がった。'],
    next: '次は「中世ヨーロッパ(wh_europe_mid)」に進みましょう。732年にイスラーム軍を破ったフランク王国が、ローマ教会と結びついて西ヨーロッパ世界をつくります。セルジューク朝の進出が十字軍を引き起こしたように、イスラーム世界とヨーロッパの関係にも注目します。'
  };

  // ===== 中世ヨーロッパ =====
  L.wh_europe_mid = {
    goal: 'フランク王国とローマ=カトリック教会による西ヨーロッパ世界の成立、封建社会と荘園のしくみ、教皇権の盛衰、十字軍と商業の復活、そして封建社会がくずれて王権が強まるまでの流れを、因果でつないで説明できるようになる。',
    intro: 'ヨーロッパの古いお城や大聖堂の写真を見たことがあるでしょう。お城は、外敵から身を守るために領主が築いたものです。大聖堂は、人々の生活のすみずみまで教会の教えが行きわたっていたことを表しています。\n中世のヨーロッパは、【国王の力が弱く、教会の力が強い】という、今の国とはずいぶんちがう社会でした。この単元では、なぜそんな社会ができたのか、そしてそれがどうやってくずれ、近世の「強い国王の国」へ移っていくのかを学びます。2本の線、【教皇の力】と【国王の力】の上がり下がりを意識して読むと、流れがつかめます。',
    pre: '前の単元までで学んだように、ローマ帝国は395年に東西に分かれ、【西ローマ帝国】は476年に滅びました。一方、【東ローマ(ビザンツ)帝国】は続きます。\nローマ帝国の北の国境の外には、【ゲルマン人】がくらしていました。4世紀後半、アジア系の【フン人】が西へ進んで圧迫したことをきっかけに、ゲルマン人は375年ごろからローマ帝国の領内へ大規模に移動し始めました。これを【ゲルマン人の大移動】といいます。\nキリスト教は392年にローマ帝国の国教になっていました。教会の中では、ローマ・コンスタンティノープルなどの教会が有力で、ローマの教会の長はのちに【教皇】とよばれます。325年のニケーア公会議で正統とされた【アタナシウス派】と、異端とされた【アリウス派】の区別も思い出しておきましょう。多くのゲルマン人は、はじめアリウス派を信じていました。\n7〜8世紀には、イスラーム勢力が地中海の南岸からイベリア半島まで広がりました。西ヨーロッパは、東のビザンツ帝国と南のイスラーム世界に囲まれていたのです。',
    secs: [
      { h: 'フランク王国とローマ教会の結びつき', t: 'ゲルマン人の国の多くは短い期間で滅びましたが、ガリア北部の【フランク王国】は長く続き、西ヨーロッパの中心になりました。なぜでしょうか。\n481年に王になった【クローヴィス】(メロヴィング朝)は、496年ごろ、正統派の【アタナシウス派】に改宗しました。アリウス派を信じる他のゲルマン人の国とちがって、ローマ人の貴族や教会と信仰が同じになったため、その協力を得ることができたのです。\n8世紀になると、王家の力が弱まり、王の家の行政をつかさどる宮宰が実権をにぎりました。宮宰【カール=マルテル】は、732年の【トゥール・ポワティエ間の戦い】でイスラーム軍を破り、西ヨーロッパのキリスト教世界を守りました。\nその子【ピピン】は、751年に教皇の支持を得て王位につき、【カロリング朝】を開きました。ピピンはそのお礼として、北イタリアのランゴバルド王国から取り上げたラヴェンナ地方を教皇に寄進しました(756年)。これが【教皇領】の始まりです。\nピピンの子【カール大帝】(シャルルマーニュ)は、ザクセン人やランゴバルド王国を征服し、西ヨーロッパの大部分を統一しました。全国を州に分けて伯をおき、巡察使を派遣して監督させました。また、学者アルクインらを宮廷に招いてラテン語の学問を盛んにしました(カロリング=ルネサンス)。\n800年、教皇【レオ3世】は、カール大帝にローマ皇帝の冠を与えました(カールの戴冠)。ローマ教会にとっては、それまで頼っていたビザンツ皇帝から自立し、新しい保護者を得たことを意味します。こうして、【古代ローマの文化・キリスト教・ゲルマン人】の3つの要素が結びついた【西ヨーロッパ世界】が成立しました。\nカール大帝の死後、王国は843年の【ヴェルダン条約】と870年の【メルセン条約】で分割され、それぞれ、のちのドイツ・フランス・イタリアのもとになりました。東フランクでは、962年に【オットー1世】が教皇から皇帝の冠を受け、のちに【神聖ローマ帝国】とよばれる国が始まりました。西フランクでは、987年にカロリング家が断絶して【カペー朝】が始まりました。',
        key: 'クローヴィスの改宗(アタナシウス派)→ カール=マルテルの勝利(732年)→ ピピンの寄進(教皇領)→ カールの戴冠(800年)で西ヨーロッパ世界が成立。分裂後、962年神聖ローマ帝国・987年カペー朝。',
        chain: { title: 'フランク王国とローマ教会が結びつくまで', items: [
          ['できごと', 'クローヴィスがアタナシウス派に改宗(496年ごろ)', 'ローマ人貴族・教会の支持を得る'],
          ['できごと', 'カール=マルテルがイスラーム軍を破る(732年)', 'トゥール・ポワティエ間の戦い'],
          ['できごと', 'ピピンがカロリング朝を開く(751年)・ピピンの寄進(756年)', '教皇領の始まり'],
          ['結果', 'カールの戴冠(800年)', 'ローマ教会がビザンツ皇帝から自立'],
          ['意味', '西ヨーロッパ世界の成立', 'ローマの文化・キリスト教・ゲルマン人の融合']] },
        ex: [{ q: 'カール大帝の戴冠(800年)が、ローマ教会にとってどのような意味をもったか説明しよう。', hint: 'それまでローマ教会を保護していたのはだれだったかを考えましょう。', steps: ['西ローマ帝国が滅んだあと、ローマ教会はビザンツ皇帝の保護を受ける立場にあった。', 'しかし、ビザンツ皇帝とローマ教会のあいだには、聖像の問題などで対立が生じていた。', 'ローマ教会は、西ヨーロッパを統一したフランク王国を新しい保護者にしようとした。', 'カールにローマ皇帝の冠を与えたことで、ローマ教会はビザンツ皇帝から自立した。'], a: 'ビザンツ皇帝にかわる新しい政治的な保護者をフランク王国に得て、ローマ教会がビザンツ皇帝から自立することを意味した。', check: '「ビザンツ皇帝からの自立」と「新しい保護者」の両方が入っているかを確かめます。' }] },
      { h: '封建社会と荘園:自分の身は自分で守る社会', t: '9〜10世紀、西ヨーロッパは再び外部からの侵入に苦しみました。北からは【ノルマン人】(ヴァイキング)、東からはマジャール人、南からはイスラーム勢力が攻めてきたのです。王の力は弱く、人々を守ることができませんでした。\nそこで、有力者どうしが身を守るために結んだのが、【封建的主従関係】です。主君は家臣に土地(【封土】)を与えて保護し、家臣は主君に【軍役】などで忠誠をつくしました。このしくみは、ローマ末期の恩貸地制度(土地を有力者に預けて保護を受ける)と、ゲルマン人の従士制(戦士が首長に忠誠を誓う)が結びついてできたとされます。\n中世ヨーロッパの主従関係の特徴は、主君と家臣の両方に義務がある【双務的な契約】だったことです。主君が義務を果たさなければ、家臣は契約を破ることができました。また、家臣は複数の主君と契約を結ぶこともできました。そのため、王の力は全国にはなかなか及びませんでした。\n領主の経済的な基盤は、【荘園】でした。荘園は、領主が直接経営する領主直営地と、農民が耕作する農民保有地などからなります。荘園で働く農民の多くは【農奴】とよばれ、移動や職業を選ぶ自由がありませんでした。農奴は、領主直営地で働く【賦役】と、自分の保有地でとれた作物を納める【貢納】の義務を負い、ほかに結婚税や死亡税も払いました。さらに、教会には収穫の10分の1を納める十分の一税がありました。\n領主は、国王の役人が荘園に入って税を取ったり裁判をしたりすることを拒む【不輸不入権】をもち、荘園の中では裁判も行いました(領主裁判権)。\n11世紀ごろからは、耕地を3つに分けて、秋まき・春まき・休耕をくり返す【三圃制】や、重い鉄の刃をもつ有輪犂が普及し、農業生産が増えました。この生産の増加が、のちの人口増加や商業の復活の土台になります。',
        key: '外敵の侵入の中で、封土と軍役による双務的な主従関係が成立。荘園では農奴が賦役と貢納を負い、領主は不輸不入権をもった。王の力が弱い分権的な社会。' },
      { h: 'ローマ=カトリック教会と教皇権の最盛期', t: '中世の西ヨーロッパでは、人々は生まれてから死ぬまで教会と関わって生きました。洗礼・結婚・葬儀などの儀式は教会が行い、教会の外では救われないと考えられていたからです。\nローマ=カトリック教会は、【教皇】を頂点に、大司教・司教・司祭と続く【階層制組織】をつくりました。教会や修道院は、寄進によって広い土地をもつ大領主でもありました。\n修道院も重要な役割をはたしました。6世紀にベネディクトゥスがイタリアのモンテ=カシノに建てた修道院では、「祈り、働け」をモットーに、清貧・純潔・服従の戒律が守られ、修道士は開墾や学問にも励みました。\nしかし、教会が富と土地をもつようになると、聖職を売買したり、聖職者が妻をもったりするなど、乱れも生まれました。また、皇帝や国王などの世俗の権力者が、聖職者を任命する権利(【聖職叙任権】)をにぎっていました。これを改めようとしたのが、910年にフランスに建てられた【クリュニー修道院】を中心とする改革運動です。\n改革を進めた教皇【グレゴリウス7世】は、聖職叙任権を教会に取りもどそうとして、神聖ローマ皇帝【ハインリヒ4世】と対立しました(【叙任権闘争】)。教皇に破門された皇帝は、ドイツの諸侯が離反したため、1077年にイタリアのカノッサで教皇に許しを請いました。これを【カノッサの屈辱】といいます。叙任権闘争は、1122年の【ヴォルムス協約】で、聖職叙任権が教皇にあることを認める形で決着しました。\n13世紀初めの教皇【インノケンティウス3世】のとき、教皇権は最盛期をむかえました。彼は、イギリスのジョン王を破門し、フランスの国王を屈服させるなど、各国の王を従わせました。「教皇は太陽、皇帝は月」という彼のことばは、教皇の権威が皇帝より上であるという考えを表しています。',
        key: '教皇を頂点とする階層制組織。クリュニー修道院の改革 → 叙任権闘争(カノッサの屈辱1077年・ヴォルムス協約1122年)→ インノケンティウス3世で教皇権が最盛期。' },
      { h: '十字軍と商業・都市の発展', t: '11世紀、トルコ人のセルジューク朝がアナトリアに進出し、ビザンツ帝国を圧迫しました。ビザンツ皇帝はローマ教皇に救援を求め、教皇【ウルバヌス2世】は1095年の【クレルモン宗教会議】で、聖地イェルサレムの回復をよびかけました。これが【十字軍】の始まりです。\n参加した人々の目的はさまざまでした。教皇は東西の教会を統一する主導権をにぎりたいと考え、諸侯や騎士は新しい領地を、商人は商業上の利益を求めました。背景には、三圃制などで農業生産が増えて人口が増え、西ヨーロッパ全体が外へ向かって拡大していたことがあります。\n【第1回十字軍】(1096〜99年)はイェルサレムを占領して【イェルサレム王国】を建てました。しかし、12世紀後半、アイユーブ朝の【サラディン】がイェルサレムを取りもどし、第3回十字軍はイェルサレムを回復できませんでした。【第4回十字軍】(1202〜04年)は、ヴェネツィア商人の意向で、同じキリスト教国のビザンツ帝国の都コンスタンティノープルを占領し、ラテン帝国を建てました。こうして十字軍は、本来の目的から大きくはずれていきました。結局、十字軍は聖地の回復という目的を果たせずに終わりました。\n十字軍の結果、【教皇の権威は低下】し、遠征を指揮した【国王の権威は高まり】ました。一方、多くの諸侯や騎士は、遠征で財産を失ったり戦死したりして没落しました。\n十字軍の輸送などを通じて、地中海の交易がさかんになりました。ヴェネツィアやジェノヴァなど北イタリアの都市は、香辛料などアジアの産物を扱う【東方貿易(レヴァント貿易)】で栄えました。北海・バルト海では、毛織物・木材・海産物などが取り引きされ、リューベックを盟主とする北ドイツの都市が【ハンザ同盟】を結びました。2つの交易圏を結ぶフランスのシャンパーニュ地方では、定期的な大市が開かれました。\n商業の発展とともに都市が成長しました。都市は、国王や皇帝から特許状を得て、領主の支配からはなれた【自治都市】になるものもありました。都市の中では、商人や手工業者が同業者の組合【ギルド】をつくり、価格や品質を取り決めて、自分たちの利益を守りました。',
        key: '十字軍(1096年〜)は聖地回復に失敗 → 教皇の権威低下・国王の権威上昇・諸侯騎士の没落。東方貿易(北イタリア)とハンザ同盟(北ドイツ)で商業と都市が発展した。',
        ex: [{ q: '次の十字軍に関する文を、古い順に並べよう。ア 第4回十字軍がコンスタンティノープルを占領した イ 教皇ウルバヌス2世がクレルモン宗教会議でよびかけた ウ 第1回十字軍がイェルサレム王国を建てた エ サラディンがイェルサレムを奪回した', hint: 'イェルサレムが「キリスト教徒のもの → イスラーム教徒のもの」と動いた順を考えましょう。', steps: ['まず、十字軍のよびかけ(1095年)が最初にくるのでイ。', '次に、第1回十字軍(1096〜99年)がイェルサレムを占領して王国を建てたウ。', 'その後、12世紀後半にサラディンがイェルサレムを奪回したエ。', '最後に、第4回十字軍(1202〜04年)がコンスタンティノープルを占領したア。'], a: 'イ → ウ → エ → ア', check: 'サラディンとの戦いは第3回十字軍のきっかけなので、第1回と第4回のあいだに入ることを確かめます。' }] },
      { h: '中世の終わり:封建社会のゆらぎと王権の強化', t: '商業がさかんになり、貨幣が農村にも広まると、領主は賦役のかわりに、生産物や貨幣で地代を納めさせるようになりました。農民は、地代を納めた残りを自分のものにできるため、豊かになる者も現れ、農奴の身分から解放される者も出てきました。\n14世紀半ばには、【黒死病(ペスト)】が大流行し、ヨーロッパの人口の約3分の1が失われたといわれます。働き手が減ったため、農民の地位はさらに向上しました。これに対し、領主が農民への束縛を再び強めようとすると、農民は反乱を起こしました。フランスの【ジャックリーの乱】(1358年)や、イギリスの【ワット=タイラーの乱】(1381年)です。こうした中で、荘園にもとづく封建社会はくずれていきました。\n教会の権威もゆらぎました。1303年、教皇ボニファティウス8世は、聖職者への課税をめぐって対立したフランス王【フィリップ4世】にとらえられました(【アナーニ事件】)。その後、教皇庁は南フランスのアヴィニョンに移され、フランス王の影響を受けました(1309〜77年、「教皇のバビロン捕囚」)。さらに、ローマとアヴィニョンに教皇が並び立つ【教会大分裂】(1378〜1417年)が起こり、教皇の権威は大きく下がりました。イギリスのウィクリフやベーメンのフスは教会を批判し、【コンスタンツ公会議】(1414〜18年)で教会大分裂は終わりましたが、フスは異端とされて処刑されました。\n一方で、国王の力が強まりました。イギリスとフランスは、フランドル地方や王位継承をめぐって【百年戦争】(1339〜1453年)を戦いました。フランスは一時危機におちいりましたが、【ジャンヌ=ダルク】の活躍で立ち直り、最終的にイギリスを大陸からほぼ追い出しました。この戦争では長弓兵や火砲が活躍し、一騎打ちをする騎士の役割が小さくなって、諸侯・騎士は没落しました。\nイギリスでは、百年戦争のあと王位をめぐる【バラ戦争】(1455〜85年)が起こり、多くの貴族が没落しました。勝ったヘンリ7世が1485年に【テューダー朝】を開き、王権を強めました。イベリア半島では、キリスト教徒がイスラーム勢力から土地を取りもどす【レコンキスタ(国土回復運動)】が進み、1479年に成立した【スペイン王国】が、1492年にイスラーム最後の拠点グラナダを攻め落としました。\nこうして、教皇と諸侯の力が弱まり、国王を中心にまとまる国が形づくられていきました。これが、次の近世の主権国家・絶対王政へとつながります。',
        key: '貨幣地代・黒死病で農民の地位が上がり、荘園制がくずれる。アナーニ事件・教皇のバビロン捕囚・教会大分裂で教皇権が低下。百年戦争・バラ戦争で諸侯が没落し、王権が強まった。',
        flow: { title: '教皇の力と国王の力(上から下へ時代が進む)', cols: 2, head: ['教皇・教会', '国王・諸侯'], rows: [
          [['カールの戴冠(800年)', 'b', 1, '教会がフランク王国と結ぶ'], ['封建社会の成立', 'k', 1, '王の力は弱く分権的']],
          [['カノッサの屈辱(1077年)', 'rr', 1, '教皇が皇帝に勝つ'], ['叙任権闘争', 'k', 1, 'ヴォルムス協約(1122年)']],
          [['インノケンティウス3世', 'rr', 1, '13世紀初め・教皇権の最盛期'], ['十字軍(1096年〜)', 'o', 1, '諸侯・騎士が没落し始める']],
          [['アナーニ事件(1303年)', 'b', 1, '教皇が仏王にとらえられる'], ['フィリップ4世', 'g', 1, '三部会を開き国内をまとめる']],
          [['教会大分裂(1378〜1417年)', 'b', 1, '教皇の権威が大きく低下'], ['百年戦争・バラ戦争', 'g', 1, '諸侯・騎士の没落・王権の強化']]
        ], legend: [['rr', '教皇権が強い'], ['b', '教会の転機'], ['k', '分権的な時代'], ['o', '十字軍'], ['g', '王権の強化']] } },
      { h: 'もっと深く:東のビザンツ帝国と、西のカトリック世界', t: '同じキリスト教の世界でも、東のビザンツ帝国と西のカトリック世界は、まったくちがう道を歩みました。そのちがいを比べると、西ヨーロッパの特徴がよく分かります。\n第一のちがいは、【皇帝と教会の関係】です。西では、教皇と皇帝・国王が別々の権力として並び立ち、叙任権闘争のように争いました。東のビザンツ帝国では、皇帝が政治の支配者であるとともに、コンスタンティノープル教会を支配し、教会の上に立ちました。\n第二のちがいは、【政治のしくみ】です。ビザンツ帝国は、ローマ帝国の官僚制を受けつぎ、皇帝が専制的に支配する中央集権の国でした。西ヨーロッパのように、王の力が弱い分権的な封建社会にはなりませんでした。6世紀の【ユスティニアヌス帝】は、一時は地中海の大部分を回復し、法学者に命じて『ローマ法大全』を編纂させ、首都に【ハギア=ソフィア聖堂】を建てました。また、ビザンツ帝国では金貨が使われ続け、コンスタンティノープルは東西交易の中心として栄えました。\n第三のちがいは、【宗教】です。726年、ビザンツ皇帝レオン3世が【聖像禁止令】を出したことで、ゲルマン人への布教に聖像を使っていたローマ教会と対立が深まりました。両者は1054年にたがいに破門しあい、西の【ローマ=カトリック教会】と東の【ギリシア正教会】に分かれました。\nビザンツ帝国は、その後、十字軍(第4回)による首都の占領などで弱まりながらも続き、1453年に【オスマン帝国】に滅ぼされました。ビザンツ帝国が残したギリシアの古典や学問は、イタリアに逃れた学者によって伝えられ、ルネサンスに影響を与えました。また、ギリシア正教は、スラヴ人の世界、とくにロシアに受けつがれました。\nつまり、【西=教会と王権の二本立て・分権的】【東=皇帝が教会も支配・中央集権的】と整理できます。西ヨーロッパの「王の力が弱い」状態は、ヨーロッパに共通の性質ではなく、西ヨーロッパ独特の特徴だったのです。',
        key: '西=教皇と皇帝・国王が並び立つ分権的な社会。東(ビザンツ)=皇帝が教会も支配する中央集権の国。1054年に東西教会が分離した。' },
      { h: '入試ではこう出る:十字軍の影響と、似た用語の区別', t: '中世ヨーロッパの入試では、【十字軍の影響】が論述でも選択でももっともよく問われます。答案では、(1)教皇の権威の低下、(2)国王の権威の上昇、(3)諸侯・騎士の没落、(4)東方貿易の発展と北イタリア都市の繁栄、(5)イスラーム・ビザンツの文化の流入、の5つから、字数に応じて選んで書きます。\n選択問題では、【似た用語・似た事件の取りちがえ】がねらわれます。ヴェルダン条約(843年)とメルセン条約(870年)、カノッサの屈辱(1077年)とアナーニ事件(1303年)、ジャックリーの乱(フランス)とワット=タイラーの乱(イギリス)、ハンザ同盟(北ドイツ)とロンバルディア同盟(北イタリア)などです。\nとくに、カノッサの屈辱とアナーニ事件は、「教皇が勝った事件」と「教皇が負けた事件」という正反対の意味をもちます。どちらが教皇権の最盛期の前後に起きたのかを、流れの中で覚えましょう。\nまた、イギリスの議会の始まりもよく問われます。1215年、ジョン王に貴族が【マグナ=カルタ(大憲章)】を認めさせ、王でも勝手に課税できないことを確認しました。1265年にはシモン=ド=モンフォールの議会、1295年にはエドワード1世の【模範議会】が開かれました。フランスでは、1302年にフィリップ4世が【三部会】(聖職者・貴族・平民の代表の会議)を開きました。',
        key: '十字軍の影響は5つの要素から選んで書く。カノッサの屈辱(教皇の勝利)とアナーニ事件(教皇の敗北)は正反対。',
        ex: [
          { q: '十字軍が西ヨーロッパの社会に与えた影響を、政治と経済の両面から説明しよう。', hint: '政治は「だれの力が上がり、だれの力が下がったか」、経済は「どこの都市が栄えたか」で考えましょう。', steps: ['政治:十字軍は聖地回復に失敗し、よびかけた教皇の権威が下がった。', '政治:遠征を指揮した国王の権威は上がり、多くの諸侯・騎士は財産を失って没落した。', '経済:十字軍の輸送などを通じて地中海の交易がさかんになった。', '経済:ヴェネツィアなど北イタリアの都市が東方貿易で栄え、貨幣経済が広まった。'], a: '政治面では、十字軍の失敗で教皇の権威が低下し、諸侯・騎士が没落する一方、国王の権威が高まった。経済面では、地中海の交易がさかんになり、北イタリアの都市が東方貿易で栄えて、貨幣経済が広がった。', check: '政治面と経済面のそれぞれに、少なくとも2つずつ要素が入っているかを確かめます。' },
          { q: 'カノッサの屈辱とアナーニ事件を、教皇権の変化という観点から比べて説明しよう。', hint: 'それぞれの事件で、教皇は勝ったのか、負けたのかを考えましょう。', steps: ['カノッサの屈辱(1077年)は、叙任権闘争の中で、破門された神聖ローマ皇帝ハインリヒ4世が教皇グレゴリウス7世に許しを請うた事件。', 'これは、教皇の権威が皇帝より強いことを示し、教皇権が上昇していく時期のできごとである。', 'アナーニ事件(1303年)は、教皇ボニファティウス8世がフランス王フィリップ4世にとらえられた事件。', 'これは、国王の力が教皇を上回ったことを示し、教皇権が衰退していく時期のできごとである。'], a: 'カノッサの屈辱は教皇が皇帝を屈服させた事件で、教皇権の上昇を示す。アナーニ事件は教皇がフランス王にとらえられた事件で、教皇権の衰退と王権の強化を示す。', check: '2つの事件の間に、教皇権の最盛期(インノケンティウス3世・13世紀初め)と十字軍が入ることを確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '843年にフランク王国を3つに分けた条約を答えよう。', a: 'ヴェルダン条約', exp: 'ヴェルダン条約でフランク王国は東フランク・西フランク・中部フランク(ロタール)に分割されました。\n870年のメルセン条約で中部フランクの北部が東西に分けられ、のちのドイツ・フランス・イタリアのもとになりました。2つの条約は年代とセットで区別しましょう。' },
      { lv: 1, q: '荘園の農民(農奴)が、領主直営地で働く義務を何という?', a: '賦役', exp: '農奴の主な義務は、領主直営地で働く「賦役」と、自分の保有地でとれた生産物を納める「貢納」の2つです。\nほかに、結婚税・死亡税などを領主に払い、教会には十分の一税を納めました。移動の自由がなかったことも農奴の大きな特徴です。' },
      { lv: 2, q: 'クローヴィスがアタナシウス派に改宗したことは、フランク王国の発展にどのように役立ったか。', a: 'ローマ人の貴族やローマ教会と同じ正統派の信仰になったため、かれらの協力を得て、ガリアの支配を安定させることができた。', exp: '当時、多くのゲルマン人は、異端とされたアリウス派を信じていました。そのため、正統派のアタナシウス派を信じるローマ系の住民や教会とのあいだに溝がありました。\nクローヴィスは改宗によってこの溝をなくし、ローマ系住民と教会を味方につけました。これが、のちにフランク王国とローマ教会が強く結びつく出発点になりました。' },
      { lv: 2, q: '黒死病の流行が、農民の地位を向上させたのはなぜか。', a: '黒死病で人口が大きく減り、働き手が不足したため、領主は農民を確保するために待遇をよくせざるをえなくなったから。', exp: '14世紀半ばの黒死病で、ヨーロッパの人口の約3分の1が失われたといわれます。\n働き手が少なくなると、労働力の価値が上がります。領主は、農民に逃げられないよう地代を軽くしたり、身分の束縛をゆるめたりしました。\nこれに対して、領主が再び束縛を強めようとしたことが、ジャックリーの乱やワット=タイラーの乱の原因になりました。' },
      { lv: 3, q: '中世西ヨーロッパの封建社会で、国王の権力が弱かった理由を80字程度で説明しよう。(記述)', a: '(模範解答)外敵の侵入の中で有力者どうしが主従関係を結んで身を守り、主従関係は双務的な契約で家臣が複数の主君をもつこともできたうえ、領主は不輸不入権をもって荘園を独自に支配したから。(87字)', exp: 'この問題では、「主従関係のしくみ」と「荘園のしくみ」の両面から説明することが求められます。\n主従関係の面では、国王が全国の人々と直接つながっていたのではなく、主君と家臣の契約が何重にも重なっていました。しかも契約は双務的で、家臣は複数の主君をもつこともできたため、国王への忠誠は絶対ではありませんでした。\n荘園の面では、領主は不輸不入権によって国王の役人の立ち入りや課税を拒み、領主裁判権ももっていました。\n採点のポイントは、(1)外敵の侵入と自衛のための主従関係、(2)双務的な契約・複数の主君、(3)不輸不入権による荘園の独立、の3点です。' },
      { lv: 3, q: '14〜15世紀に、西ヨーロッパで国王の権力が強まった理由を、諸侯・騎士と教皇の変化に注目して説明しよう。(記述)', a: '(模範解答)十字軍や百年戦争・バラ戦争で諸侯・騎士が没落し、火砲や長弓の普及で騎士の軍事的な役割も小さくなった。また、黒死病や貨幣経済の広がりで荘園制がくずれた。教皇もアナーニ事件や教会大分裂で権威を失ったため、国王が国内をまとめる中心になった。', exp: '国王の力が強まったのは、国王自身が強くなっただけでなく、国王と競い合っていた「諸侯・騎士」と「教皇」の力が弱まったからです。\n諸侯・騎士は、十字軍の失敗や百年戦争・バラ戦争で没落しました。戦い方も、長弓兵や火砲が中心になり、騎士の役割が小さくなりました。荘園制のくずれも、領主の経済的な力を弱めました。\n教皇は、アナーニ事件(1303年)、教皇のバビロン捕囚、教会大分裂(1378〜1417年)で権威を失いました。\n採点のポイントは、(1)諸侯・騎士の没落とその理由、(2)荘園制のくずれ、(3)教皇権の衰退とその具体的なできごと、の3点です。' }
    ],
    faq: [
      ['神聖ローマ帝国は、古代のローマ帝国と同じ国なの?', 'ちがいます。【神聖ローマ帝国】は、962年に東フランク(ドイツ)のオットー1世が教皇から皇帝の冠を受けたことに始まる国で、中心はドイツです。\n「ローマ皇帝」の称号を受けついだことで、古代ローマ帝国の後継者を名のりましたが、領土もしくみも古代のローマ帝国とは別のものです。'],
      ['十字軍は、全部で何回あったの?', '教科書では、主な十字軍を【第1回(1096〜99年)から第7回まで】数えることが多いです。数え方には説もあるので、回数そのものより、第1回(イェルサレム王国)、第3回(サラディンとの戦い)、第4回(コンスタンティノープルの占領)の内容を区別して覚えることが大切です。'],
      ['ギルドは、今の労働組合と同じもの?', '同じではありません。中世の【ギルド】は、商人や手工業の親方が中心となった同業者の組合で、価格や品質、生産量を取り決め、競争を制限して仲間の利益を守りました。\n手工業のギルドでは、親方・職人・徒弟という身分の順序があり、親方だけが正式な組合員でした。働く人どうしが経営者と交渉する今の労働組合とは、性格がちがいます。']
    ],
    terms: [['封土', '主君が家臣に与えた土地。その代わりに家臣は軍役で奉仕した'], ['農奴', '荘園の農民。移動の自由がなく、賦役・貢納の義務を負った'], ['不輸不入権', '国王の役人の課税や立ち入りを拒む領主の権利'], ['聖職叙任権', '司教などの聖職者を任命する権利。教皇と皇帝が争った'], ['十字軍', '聖地イェルサレムの回復を目的とした、西ヨーロッパのキリスト教徒の遠征'], ['ハンザ同盟', 'リューベックを盟主とする北ドイツの都市同盟。北海・バルト海の交易を支配'], ['ギルド', '中世都市の商人や手工業者の同業者組合'], ['教会大分裂', '1378〜1417年、ローマとアヴィニョンなどに教皇が並び立った状態']],
    miss: ['カール=マルテルとカール大帝を同じ人物と思う。カール=マルテルは宮宰(732年の戦い)、カール大帝はその孫で800年に戴冠した国王。間にピピンが入る「祖父 → 父 → 子」の関係で覚える。', '中世の主従関係を、家臣が一方的に従う関係と思う。主君と家臣の双方に義務がある双務的な契約で、家臣は複数の主君をもつこともできた。', 'カノッサの屈辱を「教皇が皇帝に屈服した事件」と逆に覚える。屈服したのは皇帝ハインリヒ4世。教皇が負けたのはアナーニ事件(1303年)。', '十字軍の結果、教皇の権威が高まったと思う。十字軍は目的を果たせず失敗し、教皇の権威は低下した。上がったのは国王の権威。', 'ジャックリーの乱とワット=タイラーの乱の国を逆にする。ジャックリー=フランス(1358年)、ワット=タイラー=イギリス(1381年)。「ジャック」はフランス語の名前、と覚える。'],
    sum: ['クローヴィスの改宗からカールの戴冠(800年)までで、フランク王国とローマ教会が結びつき、西ヨーロッパ世界が成立した。', '外敵の侵入の中で、双務的な主従関係と荘園制による封建社会ができ、国王の力は弱かった。', '叙任権闘争をへて、13世紀初めのインノケンティウス3世のときに教皇権は最盛期をむかえた。', '十字軍は失敗に終わり、教皇の権威が低下した一方、東方貿易やハンザ同盟で商業と都市が発展した。', '黒死病や貨幣経済で荘園制がくずれ、教皇権の衰退と諸侯の没落の中で、国王の権力が強まった。', 'ビザンツ帝国は皇帝が教会も支配する中央集権の国で、1054年に東西の教会は分かれた。'],
    next: '次は「東アジア世界:隋・唐・宋・元(wh_china_mid)」に進みましょう。同じころ東アジアでは、隋・唐が律令にもとづく中央集権の大帝国をつくり、13世紀にはモンゴル帝国が、ヨーロッパとイスラーム世界・中国をひとつにつなぎます。'
  };

  // ===== 東アジア世界:隋・唐・宋・元 =====
  L.wh_china_mid = {
    goal: '隋・唐の律令国家のしくみと、その変化(安史の乱・両税法)、宋の文治主義と経済の発展、モンゴル帝国と元による東西の結びつきを、「土地・税・兵」と「だれが政治をになうか」の観点から説明できるようになる。',
    intro: '日本の奈良時代の平城京は、唐の都長安をまねてつくられました。律令、戸籍、班田収授法も、唐のしくみを手本にしたものです。中国の王朝の変化は、そのまま日本や朝鮮の歴史にも大きな影響を与えてきました。\nこの単元で学ぶ6世紀末から14世紀の中国は、【貴族の時代(隋・唐)】から【士大夫の時代(宋)】へ、そして【モンゴル人が支配した時代(元)】へと大きく変わります。王朝の名前を覚えるだけでなく、「土地のしくみ・税のしくみ・兵のしくみ」が1セットで変わることに注目すると、なぜ王朝が栄え、なぜ衰えたのかが見えてきます。',
    pre: '前の単元で学んだ【漢】は、220年に滅びました。その後、約370年にわたって中国は分裂の時代に入ります。魏・呉・蜀の【三国時代】をへて、北では遊牧民が次々と国を建て(五胡十六国)、やがて鮮卑の拓跋氏が建てた【北魏】が439年に華北を統一しました。南では、漢民族の王朝が建康(今の南京)を都に交代しました。これを【南北朝時代】といいます。\n北魏の孝文帝は、485年に【均田制】を始めました。国が農民に土地を割り当て、そのかわりに税を納めさせる制度です。隋・唐の土地制度は、この均田制を受けついだものです。\nこの分裂の時代には、地方の有力な家柄が代々高い官職を独占しました。こうした家柄を【門閥貴族】といいます。官吏を推薦で選ぶ九品中正という制度が、結果的に貴族の家柄を固定する役割をはたしました。\n南朝では、北から移ってきた人々によって【江南(長江の下流域)】の開発が進みました。この江南の経済力が、のちの中国全体をささえることになります。',
    secs: [
      { h: '隋:南北の統一と、新しい制度の始まり', t: '581年、北朝の北周の外戚だった楊堅(【文帝】)が【隋】を建て、589年に南朝の陳を倒して、約370年ぶりに中国を統一しました。\n文帝は、北朝から受けついだ【均田制】・【租調庸制】・【府兵制】を整えました。均田制で農民に土地を割り当て、租調庸制でその農民から税を取り、府兵制で同じ農民から兵士を出させるという、土地・税・兵が一体となったしくみです。\nさらに文帝は、それまでの九品中正をやめ、学科試験によって官吏を選ぶ【科挙】を始めました。家柄ではなく試験で人材を選ぶことで、貴族の力をおさえ、皇帝の力を強めようとしたのです。ただし、隋・唐の時代には、まだ貴族の力が強く残っていました。\n2代目の【煬帝】は、華北と江南を結ぶ【大運河】を完成させました。江南でとれる豊かな米などの物資を、政治の中心である北方へ運ぶためです。大運河は、その後の中国の経済をささえる大動脈になりました。\nしかし、煬帝は大運河の建設などで人々を大量に動員したうえ、3度にわたる【高句麗遠征】に失敗しました。重い負担に苦しむ人々の反乱が各地で起こり、隋は618年に滅びました。秦と同じように、統一を果たしながら、急激な負担で短期間に滅んだ王朝です。\nなお、日本からは607年に小野妹子が遣隋使として派遣されています。',
        key: '隋(581年〜)は589年に南北を統一。均田制・租調庸制・府兵制を整え、科挙を始めた。煬帝の大運河と高句麗遠征の失敗で618年に滅亡。' },
      { h: '唐:律令国家と東アジアの国際秩序', t: '618年、隋の武将だった李淵(【高祖】)が【唐】を建て、長安を都としました。2代目の【太宗】(李世民)は国内を安定させ、その治世は「貞観の治」とたたえられました。\n唐は、【律令格式】という法の体系にもとづいて国を治めました。律は刑法、令は行政法などで、格・式はその補足や施行細則です。中央には【三省六部】がおかれました。皇帝の命令(詔勅)を【中書省】が起草し、【門下省】が審議し、【尚書省】がその下の六部(吏部・戸部・礼部・兵部・刑部・工部)を通じて実行しました。門下省は貴族の意見を代表する役所で、詔勅に反対することもできました。また、官吏を監察する御史台もおかれました。\n土地・税・兵のしくみは、隋を受けついだ【均田制・租調庸制・府兵制】です。租は穀物、調は絹などの布、庸は労役(またはその代わりの布)です。均田制で土地をもらった農民が、税と兵役の両方をになったことに注意しましょう。\n唐は、周辺の異民族を征服すると、【都護府】をおいて監督させ、その地の有力者に統治をまかせました(羈縻政策)。また、周辺国の王に官位を与えて君臣関係を結ぶ【冊封】と、周辺国が貢ぎ物を送る【朝貢】を通じて、東アジアの国際秩序をつくりました。朝鮮半島の新羅、中国東北地方の渤海、日本などは、唐の制度や文化を取り入れました。\n唐の都【長安】は、人口100万ともいわれる国際都市でした。シルクロードを通じてソグド人などの商人が集まり、景教(ネストリウス派キリスト教)・祆教(ゾロアスター教)・マニ教の寺院も建てられました。文化では、李白・杜甫・白居易の詩や、顔真卿の書が知られています。仏教では、【玄奘】がインドに行き、ナーランダー僧院で学んで多くの経典を持ち帰り、旅の記録として『大唐西域記』を残しました。\n7世紀後半、高宗の皇后だった【則天武后】は、自ら皇帝となって国号を周と改めました(690年)。その後、唐が復活し、8世紀前半の【玄宗】の時代には「開元の治」とよばれる繁栄がもたらされました。',
        key: '唐の三省六部:中書省が起草・門下省が審議・尚書省が実行。均田制・租調庸制・府兵制は農民が土地・税・兵をすべてになうしくみ。冊封と朝貢で東アジアの国際秩序をつくった。',
        ex: [{ q: '唐の三省について、詔勅が出されてから実行されるまでの流れを説明しよう。', hint: '「起草 → 審議 → 実行」の3段階で考えましょう。', steps: ['まず、中書省が皇帝の命令(詔勅)の文案をつくる(起草)。', '次に、門下省がその内容を審議する。門下省は、内容に反対して差しもどすこともできた。', '審議を通った詔勅は、尚書省に送られる。', '尚書省は、その下の六部(吏部・戸部・礼部・兵部・刑部・工部)を通じて、詔勅を実行する。'], a: '中書省が詔勅を起草し、門下省が審議して、尚書省が六部を通じて実行する。', check: '「中書 → 門下 → 尚書」の順番と、それぞれの役割(起草・審議・実行)がそろっているかを確かめます。' }] },
      { h: '安史の乱と唐の変質:土地・税・兵のしくみが変わる', t: '唐の前半のしくみは、均田制で農民に土地を与え、その農民から税と兵を取るというものでした。しかし、人口が増えて割り当てる土地が不足し、さらに有力者が土地を集めて大きな荘園をつくるようになると、均田制はうまくいかなくなりました。重い負担からのがれるため、土地をすてて逃げる農民も増えました。\n農民が減ると、府兵制で兵士を集めることもむずかしくなります。そのため唐は、兵士を雇う【募兵制】に変え、辺境の防衛には、軍隊を指揮する【節度使】をおきました。\n755年、節度使の【安禄山】とその部下の史思明が反乱を起こしました。これを【安史の乱】(755〜763年)といいます。反乱は、ウイグルの援軍などを得てようやくおさえられましたが、唐の力は大きく弱まりました。乱の後、各地の節度使は、軍事だけでなく行政・財政の権限もにぎって半ば独立した勢力(【藩鎮】)となりました。\n均田制がくずれたため、唐は780年、宰相楊炎の提案で【両税法】を始めました。両税法は、土地を割り当てた農民に一律に課税するのではなく、【実際に住んでいる土地】で、【所有する土地や財産に応じて】、【夏と秋の2回】税を取る制度です。これは、国が土地を割り当てることをあきらめ、大土地所有を事実上認めたことを意味します。\nその後、塩の専売に反発した塩の密売人による【黄巣の乱】(875〜884年)が起こり、唐の支配は大きくゆらぎました。907年、節度使の【朱全忠】によって唐は滅ぼされ、華北で5つの王朝が交代し、他の地方で多くの国が分立する【五代十国】の時代になりました。',
        key: '均田制のくずれ → 府兵制から募兵制へ・節度使 → 安史の乱(755〜763年)→ 藩鎮の自立。税は租調庸制から両税法(780年)へ。黄巣の乱をへて907年に滅亡。',
        chain: { title: '唐の変質:土地・税・兵のしくみの変化', items: [
          ['背景', '人口の増加と大土地所有の広がりで、均田制がくずれる', '負担をのがれて逃げる農民が増える'],
          ['変化', '府兵制から募兵制へ・辺境に節度使をおく', '兵士は雇われる職業軍人に'],
          ['できごと', '安史の乱(755〜763年)', '節度使の安禄山・史思明の反乱'],
          ['結果', '節度使が藩鎮として自立・780年に両税法', '資産に応じて夏と秋の2回課税'],
          ['その後', '黄巣の乱(875年〜)をへて907年に唐が滅亡', '五代十国の時代へ']] },
        ex: [{ q: '両税法と租調庸制のちがいを、「何を基準に課税するか」に注目して説明しよう。', hint: '租調庸制は、均田制とセットのしくみでした。', steps: ['租調庸制は、均田制で国から土地を割り当てられた農民(成年男子)に、一律に穀物・布・労役を課した。', 'つまり、基準は「土地を割り当てられた一人ひとりの人」である。', '両税法は、実際に住んでいる土地で、その人が所有する土地や財産の多さに応じて課税した。', 'つまり、基準は「所有する土地・財産」であり、大土地所有を事実上認めたしくみである。'], a: '租調庸制は、均田制で土地を割り当てられた成年男子に一律に課税したが、両税法は、現住地で、所有する土地や財産に応じて夏と秋の2回課税した。', check: '「一律」と「資産に応じて」という対比が答えに入っているかを確かめます。' }] },
      { h: '宋:文治主義と、士大夫・経済の時代', t: '960年、五代の後周の武将だった趙匡胤(【太祖】)が【宋】を建て、開封を都としました。唐の滅亡が節度使の自立から始まったことを反省し、太祖は節度使の力をうばい、武人ではなく、科挙で選ばれた文人の官僚に政治をまかせました。これを【文治主義】といいます。\n宋では【科挙】が整えられ、最終試験として、皇帝自らが試験官となる【殿試】が始まりました。皇帝が直接選んだ官僚は、皇帝に忠実になります。科挙に合格して官僚となり、地方の地主でもある知識人層を【士大夫】といいます。こうして、家柄で地位が決まる貴族は姿を消し、政治の中心は士大夫に移りました。\nしかし、文治主義は軍事力の弱さにもつながりました。北方では、契丹人の【遼】が力をのばし、宋は1004年に【澶淵の盟】を結んで、毎年、遼に銀や絹を贈ることで和平を保ちました。西北のタングート人の【西夏】にも、同じように銀や絹を贈りました。こうした出費と、増え続ける官僚や兵士への支出で、財政は苦しくなりました。\n11世紀後半、神宗に登用された【王安石】は、【新法】とよばれる改革を行いました。農民に低い利子でお金や穀物を貸す青苗法、中小商人に資金を貸す市易法、農民を組織して治安と兵力を確保する保甲法などです。しかし、大地主や大商人の利益をおさえる内容だったため、司馬光らの旧法党が反対し、新法党と旧法党の争いが続きました。\n12世紀初め、中国東北地方の女真人が【金】を建て、宋と結んで遼を滅ぼしました(1125年)。しかし、その後、宋と金は対立し、金は宋の都開封を攻め落として、上皇と皇帝を北へ連れ去りました(【靖康の変】、1126〜27年)。皇帝の弟が江南にのがれて宋を再興し、臨安(今の杭州)を都としました。これ以前を【北宋】、以後を【南宋】といいます。',
        key: '宋は文治主義で、殿試を加えた科挙で選ばれた士大夫が政治をになった。軍事力が弱く、遼(澶淵の盟)・西夏に銀や絹を贈った。王安石の新法と党争。靖康の変で北宋が滅び、南宋は臨安へ。',
        flow: { title: '隋から元までの王朝と北方の勢力', cols: 2, head: ['中国の王朝', '北方・周辺の勢力'], rows: [
          [['隋(581〜618年)', 'o', 1, '589年に南北統一・科挙'], ['突厥・高句麗', 'k', 1, '高句麗遠征の失敗']],
          [['唐(618〜907年)', 'o', 1, '律令・三省六部'], ['新羅・渤海・日本', 'gr', 1, '冊封・朝貢・遣唐使']],
          [['五代十国', 'k', 1, '907年〜'], ['契丹(遼)', 'b', 1, '10世紀初め〜']],
          [['北宋(960〜1127年)', 'o', 1, '文治主義・都は開封'], ['遼・西夏 → 金', 'b', 1, '澶淵の盟(1004年)・靖康の変']],
          [['南宋(1127〜1279年)', 'o', 1, '都は臨安'], ['金 → モンゴル', 'b', 1, '1234年に金が滅亡']],
          [['元(1271〜1368年)', 'y', 2, 'フビライが国号を元に・1279年に南宋が完全に滅亡']]
        ], legend: [['o', '中国の王朝'], ['k', '分裂・周辺'], ['gr', '唐の文化を受け入れた国'], ['b', '北方の民族の国'], ['y', 'モンゴルの王朝']] } },
      { h: '宋の経済と文化:江南の発展と商業の時代', t: '宋の時代には、中国の経済が大きく発展しました。その中心は【江南】です。長江下流域では、ひでりに強い品種の占城稲が取り入れられ、低湿地の開発も進んで、米の生産が大きく増えました。「【蘇湖(江浙)熟すれば天下足る】」(長江下流域が豊作なら、国じゅうの食料が足りる)ということわざが生まれたほどです。\n商業もさかんになりました。唐の時代には、都の商業は決められた区域(市)に限られていましたが、宋ではその制限がなくなり、城外や交通の要地に草市や鎮とよばれる商業の町が生まれました。商人の同業組合を行、手工業者の組合を作といいます。\n取り引きが増えると、大量の銅銭を持ち運ぶのが不便になり、手形から発展した紙幣が使われるようになりました。北宋の【交子】、南宋の【会子】です。また、江西の景徳鎮などで陶磁器の生産がさかんになり、海外にも輸出されました。海上貿易の管理のため、広州・泉州などの港には【市舶司】がおかれ、ムスリム商人も多く来航しました。\n文化の担い手は士大夫でした。宋の時代には、儒学を宇宙や人間の本性から深く考え直す宋学がおこり、南宋の【朱熹(朱子)】がこれを大成しました。これを【朱子学】といいます。朱子学は、君臣・父子などの上下の秩序を重んじる【大義名分論】や、中国を文明の中心とし周辺の民族を区別する華夷の区別を説き、のちに朝鮮や日本の江戸時代にも大きな影響を与えました。\n技術では、【木版印刷】が普及して書物が広まり、【羅針盤】や【火薬】も実用化されました。羅針盤や火薬は、のちにイスラーム世界を通じてヨーロッパに伝わり、大航海時代や戦い方の変化にも影響しました。絵画では、士大夫が教養として描く文人画が発達しました。',
        key: '宋は江南の稲作(「蘇湖熟すれば天下足る」)と商業が発展し、交子・会子の紙幣、景徳鎮の陶磁器、市舶司による海上貿易。文化の担い手は士大夫で、朱熹が朱子学を大成した。' },
      { h: 'モンゴル帝国と元:ユーラシアがつながる', t: '13世紀初め、モンゴル高原の遊牧民を統一したテムジンは、1206年、部族長の会議である【クリルタイ】で【チンギス=ハン】の位につきました。遊牧民を千戸という単位に編成し、すぐれた騎馬軍団をつくりあげました。チンギス=ハンは、中央アジアのホラズム=シャー朝を攻撃し、西夏を滅ぼしました(1227年)。\n2代目の【オゴデイ】は、1234年に【金】を滅ぼし、モンゴル高原に都カラコルムを建設しました。また、一族のバトゥがヨーロッパに遠征し、1241年のワールシュタットの戦いでドイツ・ポーランドの連合軍を破りました。さらに、【フラグ】は西アジアに遠征し、1258年にバグダードを攻め落としてアッバース朝を滅ぼしました。\n13世紀後半、モンゴル帝国は、【元】(大ハンの国)と、キプチャク=ハン国(南ロシア)、チャガタイ=ハン国(中央アジア)、イル=ハン国(イラン)などに分かれました。しかし、分かれたあともゆるやかなつながりを保ち、ユーラシアの東西の交通と交易は大いにさかんになりました。\n【フビライ】は1260年に大ハンとなり、都を大都(今の北京)に移して、1271年に国号を【元】としました。1276年には南宋の都臨安を占領し、南宋は1279年に完全に滅びました。日本にも2度遠征しましたが(1274年・1281年の元寇)、失敗しました。\n元は、モンゴル人を第一とし、中央アジア・西アジア出身の【色目人】を財務などに用い、旧金の支配下の人々(漢人)と旧南宋の人々(南人)を区別して支配しました。科挙は長く行われず、行われるようになってからも小規模で、士大夫が官僚として活躍する道はせまくなりました。\n交通では、主要な道路に一定の距離ごとに駅をおき、役人の往来や物資の輸送に使う【ジャムチ(駅伝制)】を整えました。経済では、【交鈔】とよばれる紙幣を発行し、銀も広く使われました。大運河も整備され、江南の物資を大都へ運ぶ海運も発達しました。\nこうしたネットワークを通じて、多くの人々が東西を行き来しました。イタリアの【マルコ=ポーロ】はフビライに仕え、その見聞は『世界の記述(東方見聞録)』にまとめられました。教皇の使節としてプラノ=カルピニ、フランス王ルイ9世の使節としてルブルックがモンゴルを訪れ、モンテ=コルヴィノは大都でカトリックを布教しました。モロッコ出身のイブン=バットゥータも元を訪れています。\nしかし、14世紀になると、チベット仏教の保護などによる出費や、交鈔の乱発による経済の混乱、天災が重なりました。1351年に白蓮教徒を中心とする【紅巾の乱】が起こり、その中から頭角をあらわした【朱元璋】が1368年に【明】を建てると、元はモンゴル高原に退きました。',
        key: '1206年チンギス=ハン → 1234年金を滅ぼす → 1258年アッバース朝を滅ぼす → 1271年フビライが国号を元に → 1279年南宋が滅亡。ジャムチ・交鈔で東西交流が進み、1368年明の成立で元は北へ退いた。',
        tmap: { title: 'モンゴル帝国の分かれ方(13世紀後半・模式図)', cols: 4, rows: 2, cells: [
          ['キプチャク=ハン国', 'p', 1, 1, 1, 1, '南ロシア・バトゥが建国'], ['チャガタイ=ハン国', 'p', 2, 1, 1, 2, '中央アジア'], ['元', 'y', 3, 1, 2, 1, '大ハンの国・モンゴル高原と中国・都は大都'],
          ['イル=ハン国', 'p', 1, 2, 1, 1, 'イラン・フラグが建国'], ['高麗', 'gr', 4, 2, 1, 1, '元に服属']
        ], legend: [['y', '元(大ハンの国)'], ['p', 'ハン国'], ['gr', '服属した国']], note: '位置関係だけを表した模式図です(実際の形・広さではありません)。分かれたあとも、ゆるやかなまとまりを保ちました。' } },
      { h: 'もっと深く:唐から宋へ ― 「貴族の時代」から「士大夫の時代」へ', t: '唐と宋は続いている王朝ですが、社会のしくみは大きく変わりました。この大きな変化は「唐宋変革」とよばれることがあります。変化を、政治・社会・経済の3つの面から整理してみましょう。\n【政治の担い手】は、唐の前半までは、家柄によって高い地位を代々受けつぐ【門閥貴族】でした。科挙は始まっていましたが、合格者も貴族の出身が多く、三省のうち門下省は貴族の意見を代表して皇帝の命令に反対することもできました。宋では、殿試を加えた科挙によって選ばれた【士大夫】が政治をにない、皇帝の権力がより強くなりました。貴族の力が衰えた背景には、唐末から五代の戦乱で、多くの貴族の家が没落したことがあります。\n【土地と農民】の面では、唐の前半の均田制では、国が農民に土地を割り当てていました。宋では、【大土地所有】が当たり前になり、地主が【佃戸】とよばれる小作人に土地を貸して耕作させる形が広がりました。士大夫の多くは、こうした地主の家の出身でした。\n【経済】の面では、唐の都の商業は決められた区域に限られていましたが、宋では自由な商業が広がり、紙幣も使われるようになりました。経済の中心は、華北から江南へと移りました。\nつまり、唐の前半は「国が土地を割り当て、貴族が政治をになう」社会、宋は「地主が土地をもち、試験で選ばれた士大夫が政治をになう」社会です。その転換点が、均田制のくずれと安史の乱、そして両税法でした。王朝の名前だけでなく、このような社会の変化を説明できると、論述問題に強くなります。',
        key: '唐の前半=門閥貴族・均田制・規制された商業。宋=士大夫・大土地所有(地主と佃戸)・自由な商業と江南の発展。転換点は均田制のくずれと安史の乱・両税法。' },
      { h: '入試ではこう出る:制度の変化と、王朝の区別', t: 'この分野の入試でもっともよく出るのは、【制度の変化】です。とくに「均田制・租調庸制・府兵制」から「両税法・募兵制」への変化、「貴族」から「士大夫」への変化は、選択問題でも論述問題でも定番です。\n正誤問題でのひっかけには、次のようなものがあります。「科挙は唐で始まった」(正しくは隋)、「両税法は宋で始まった」(正しくは唐の780年)、「殿試は隋で始まった」(正しくは宋)、「澶淵の盟は金と結ばれた」(正しくは遼)、「元は科挙を重視して漢人を重く用いた」(元は科挙を長く行わず、モンゴル人を第一とした)などです。\n北方民族の国の区別もよくねらわれます。【遼=契丹人】、【西夏=タングート人】、【金=女真人】の組み合わせを、宋との関係(澶淵の盟・銀や絹の贈与・靖康の変)とセットで覚えましょう。\n論述では、「宋の文治主義がもたらした影響」もよく出ます。答案では、(1)節度使の力をおさえ、科挙官僚が政治をになった(よい点)、(2)軍事力が弱く、北方民族に銀や絹を贈ることになり、財政が苦しくなった(問題点)、(3)その立て直しのため王安石の新法が行われた、という流れで書くとまとまります。',
        key: '科挙=隋、両税法=唐(780年)、殿試=宋。遼=契丹、西夏=タングート、金=女真。文治主義はよい点と問題点の両方を書く。',
        ex: [
          { q: '次の文の正誤を判断し、誤りがあれば正しく直そう。「宋は1004年、女真人の金と澶淵の盟を結び、毎年銀や絹を贈った。」', hint: '金が建てられたのは12世紀初めです。', steps: ['澶淵の盟は1004年に結ばれた和約である。', 'このとき宋が和約を結んだ相手は、契丹人の遼である。', '女真人の金が建てられたのは12世紀初め(1115年)で、1004年にはまだ存在しない。', 'したがって「女真人の金」が誤りで、「契丹人の遼」が正しい。'], a: '誤り。澶淵の盟の相手は女真人の金ではなく、契丹人の遼。', check: '年代(1004年)と国の成立時期(金は1115年)が矛盾しないかを確かめると、誤りに気づけます。' },
          { q: '宋の文治主義がもたらした影響を、よい点と問題点に分けて説明しよう。', hint: '文治主義は、唐の何を反省して始まったのかを思い出しましょう。', steps: ['文治主義は、唐が節度使の自立から滅んだことを反省し、武人の力をおさえて文人官僚に政治をまかせる政策である。', 'よい点:節度使のような地方の軍事勢力が自立することを防ぎ、科挙で選ばれた士大夫が皇帝のもとで政治をになって、皇帝の権力が安定した。', '問題点:軍事力が弱くなり、遼や西夏に銀や絹を贈って和平を保つことになった。', 'さらに、官僚や兵士への支出も増えて財政が苦しくなり、王安石の新法などの改革が必要になった。'], a: 'よい点は、節度使のような武人の自立を防ぎ、科挙で選ばれた士大夫が政治をになって皇帝の権力が安定したこと。問題点は、軍事力が弱くなり、遼や西夏に銀や絹を贈ることになって財政が苦しくなり、王安石の新法などの改革が必要になったこと。', check: 'よい点と問題点が1つずつ以上あり、問題点が王安石の新法につながっているかを確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '唐の都と、北宋・南宋の都をそれぞれ答えよう。', a: '唐=長安、北宋=開封、南宋=臨安(杭州)', exp: '唐の長安は、碁盤の目のように区画された計画都市で、日本の平城京・平安京の手本になりました。\n北宋の開封は大運河に近く、物資が集まる商業都市として栄えました。南宋は靖康の変のあと江南にのがれ、臨安を都としました。都の位置が北から南へ移ったことは、経済の中心が江南に移ったことともつながっています。' },
      { lv: 1, q: '契丹人・タングート人・女真人が建てた国を、それぞれ答えよう。', a: '契丹人=遼、タングート人=西夏、女真人=金', exp: '3つとも、宋の時代に北方や西北で力をもった国です。\n宋は遼と澶淵の盟(1004年)を結び、西夏にも銀や絹を贈りました。金は遼を滅ぼし(1125年)、さらに靖康の変で北宋を滅ぼしました。金はその後、1234年にモンゴルに滅ぼされます。' },
      { lv: 2, q: '唐で府兵制が募兵制に変わった理由を、均田制と関連づけて説明しよう。', a: '府兵制は均田制で土地を与えられた農民から兵を出させるしくみだったが、人口の増加や大土地所有の広がりで均田制がくずれ、兵役をになう農民が減ったため、兵士を雇う募兵制に変わった。', exp: '唐の前半は、「土地をもらった農民が、税も兵役もになう」というしくみでした。土地・税・兵の制度は1セットです。\nそのため、土台である均田制がくずれると、税制(租調庸制 → 両税法)も兵制(府兵制 → 募兵制)も変わらざるをえませんでした。\n募兵制で雇われた兵士を指揮した節度使が、やがて安史の乱を起こし、藩鎮として自立したことまでつなげて覚えましょう。' },
      { lv: 2, q: 'モンゴル帝国の時代に、ユーラシアの東西の交流がさかんになった理由を説明しよう。', a: 'モンゴル帝国がユーラシアの広い地域を支配し、ジャムチ(駅伝制)などで交通路を整えたため、人や物が安全に長い距離を移動できるようになったから。', exp: 'それまで、ユーラシアの東西のあいだには多くの国があり、国境を越えるたびに危険や税がありました。モンゴル帝国は、この広い地域を一つの勢力のもとにまとめました。\nさらに、ジャムチを整え、紙幣(交鈔)や銀を使った取り引きを広げたことで、商人や使節の往来がさかんになりました。マルコ=ポーロやイブン=バットゥータの旅は、この時代だからこそ可能だったのです。\n帝国が分かれたあとも、各ハン国はゆるやかなつながりを保ち、交流は続きました。' },
      { lv: 3, q: '唐の前半と宋の時代では、政治をになう人々と、その選ばれ方がどう変わったか。80字程度で説明しよう。(記述)', a: '(模範解答)唐の前半までは、家柄によって高い地位を受けつぐ門閥貴族が政治をになったが、宋では殿試を加えた科挙が整えられ、試験で選ばれた士大夫が皇帝のもとで政治をになうようになった。(86字)', exp: 'この問題の中心は「貴族から士大夫へ」という変化です。\n唐でも科挙は行われていましたが、門閥貴族の力が強く、高い地位は家柄で決まることが多くありました。唐末・五代の戦乱で貴族は没落し、宋では科挙が政治の担い手を選ぶ中心のしくみになりました。皇帝自らが試験官となる殿試によって、官僚は皇帝に忠実になり、皇帝の権力が強まりました。\n採点のポイントは、(1)唐=門閥貴族・家柄、(2)宋=科挙(殿試)で選ばれた士大夫、(3)皇帝の権力の強化、の3点です。「宋で科挙が始まった」と書くと誤りになるので注意しましょう(科挙は隋で始まった)。' },
      { lv: 3, q: '元の中国支配の特色を、人々の区別と官吏の登用に注目して説明しよう。(記述)', a: '(模範解答)元はモンゴル人を第一とし、色目人を財務などに用いる一方、旧金の支配下の漢人と旧南宋の南人を区別して支配した。科挙は長く行われず、再開後も小規模だったため、士大夫が官僚として活躍する道はせまくなった。', exp: '元の支配の特色は、民族や出身地によって人々を区別したことです。中央アジア・西アジア出身の色目人は、商業や財務の知識をもっていたため重く用いられました。\nまた、科挙は長く中止され、14世紀に再開されてからも小規模でした。そのため、宋の時代に政治をになった士大夫の多くは、官僚になる道をせばめられ、文化の面で活動しました(元曲などの庶民文化も栄えました)。\n採点のポイントは、(1)モンゴル人第一・色目人の登用、(2)漢人・南人の区別、(3)科挙が長く行われず、士大夫の活躍の場がせまくなったこと、の3点です。' }
    ],
    faq: [
      ['科挙は、いつからいつまで続いたの?', '科挙は、隋の文帝のときに始まり、唐・宋で整えられました。元では長く中止されましたが、のちに再開され、明・清でも続きました。廃止されたのは、20世紀初めの1905年(清の末期)です。\n約1300年にわたって、中国の官吏登用の中心だった制度です。'],
      ['「藩鎮」と「節度使」は同じもの?', '【節度使】は、もともと辺境の防衛のために唐がおいた軍隊の司令官の官職です。安史の乱のあと、節度使が軍事だけでなく行政や財政の権限もにぎって、半ば独立した地方勢力になりました。これを【藩鎮】とよびます。\nつまり、「官職」が節度使、「自立した勢力」としてのよび方が藩鎮です。'],
      ['元寇のとき、元はなぜ日本に勝てなかったの?', '1274年と1281年の2度の遠征では、鎌倉幕府の御家人の抵抗に加え、暴風雨によって元の船団が大きな被害を受けたことが知られています。2度目の遠征では、滅ぼした南宋の兵も多く動員されていました。\n元はその後も東南アジアなどへ遠征しましたが、海をこえる遠征では苦戦が多くなりました。']
    ],
    terms: [['均田制', '国が農民に土地を割り当て、税や兵役をになわせる土地制度。北魏で始まり、隋・唐が受けついだ'], ['科挙', '学科試験によって官吏を選ぶ制度。隋で始まり、宋で殿試が加わった'], ['三省六部', '唐の中央官制。中書省が起草、門下省が審議、尚書省が六部を通じて実行'], ['節度使', '唐が辺境においた軍隊の司令官。安史の乱のあと藩鎮として自立した'], ['両税法', '780年に唐で始まった、現住地で資産に応じて夏と秋の2回課税する税制'], ['士大夫', '宋の時代に、科挙に合格して官僚となった知識人層。地主の家の出身が多い'], ['朱子学', '南宋の朱熹が大成した儒学。大義名分論などを説いた'], ['ジャムチ', 'モンゴル帝国・元が整えた駅伝制']],
    miss: ['科挙を唐で始まったと思う。科挙を始めたのは隋の文帝。宋で殿試が加わった。「始まり=隋、完成=宋」と覚える。', '両税法を「2種類の税を取る制度」と思う。「両」は夏と秋の2回という意味。基準は、現住地で資産に応じて課税することにある。', '中書省と門下省の役割を逆にする。中書省=起草(文を書く)、門下省=審議(門の下で待ってチェックする)と、漢字のイメージで覚える。', '遼・西夏・金の民族を取りちがえる。遼=契丹、西夏=タングート、金=女真。金は遼を滅ぼし、北宋も滅ぼした、と宋との関係で順番に覚える。', 'モンゴル帝国が13世紀後半に分かれたあと、ばらばらに争うだけだったと思う。各ハン国はゆるやかなつながりを保ち、東西の交易はむしろさかんになった。'],
    sum: ['隋は589年に南北を統一し、科挙を始め、大運河を完成させたが、短期間で滅んだ。', '唐は律令・三省六部と、均田制・租調庸制・府兵制で中央集権の大帝国をつくり、冊封と朝貢で東アジアの秩序をつくった。', '均田制のくずれと安史の乱(755〜763年)で、両税法・募兵制に変わり、藩鎮が自立した。', '宋は文治主義で士大夫が政治をにない、江南の開発・商業・紙幣・朱子学が発展したが、北方民族への対応で財政が苦しくなった。', 'モンゴル帝国は1206年に成立し、元はジャムチ・交鈔でユーラシアの東西を結んだが、紅巾の乱をへて1368年に明にかわった。'],
    next: '次は「近世ヨーロッパ(wh_early_modern)」に進みましょう。モンゴル帝国の時代にヨーロッパに伝わったアジアの情報や、羅針盤・火薬などの技術が、ルネサンスや大航海時代の背景の一つになります。'
  };

  // ===== 近世ヨーロッパ =====
  L.wh_early_modern = {
    goal: 'ルネサンス・大航海時代・宗教改革が中世のしくみをどう変えたか、そしてイタリア戦争・三十年戦争をへて主権国家体制と絶対王政がどのように成立したかを、各国の具体例とともに説明できるようになる。',
    intro: '今の世界地図には、国境線がはっきり引かれ、どの国も「ほかの国から命令されない」ことが当たり前になっています。でも、中世のヨーロッパでは、教皇が国王を破門したり、一人の諸侯がいくつもの主君に仕えたりして、「国」の境目はあいまいでした。\nこの単元で学ぶ15〜18世紀は、そのあいまいな世界が、【国境と主権をもつ国どうしが並び立つ世界】に変わっていく時代です。ルネサンスで「人間」が見直され、大航海時代で世界がつながり、宗教改革で教会の力が分かれ、戦争の中で強い国王が生まれました。4つの大きな変化が、どうつながっているかを意識して読みましょう。',
    pre: '前の単元までで学んだように、中世の終わりには、十字軍の失敗や教会大分裂で【教皇の権威】が下がり、百年戦争などで【諸侯・騎士】が没落して、【国王の権力】が強まっていました。\n十字軍のころから、ヴェネツィアなどの北イタリアの都市は【東方貿易】で栄え、豊かな商人が生まれていました。また、イスラーム世界やビザンツ帝国を通じて、ギリシア・ローマの古典がヨーロッパに伝わっていました。\n1453年、【オスマン帝国】がコンスタンティノープルを攻め落とし、ビザンツ帝国が滅びました。オスマン帝国は東地中海に勢力を広げ、ヨーロッパにとって大きな脅威になります。\nイベリア半島では、【レコンキスタ】が進み、1492年にスペインがグラナダを攻め落としました。\n宋の時代に実用化された【羅針盤】や【火薬】は、イスラーム世界を通じてヨーロッパに伝わり、改良されました。これらの技術が、この単元の大きな変化をささえます。',
    secs: [
      { h: 'ルネサンス:人間らしさの再発見', t: '【ルネサンス】とは「再生」という意味で、ギリシア・ローマの古典文化を手本に、人間らしい生き方や美しさを追い求めた文化運動です。中世では、神と教会の教えが文化の中心でしたが、ルネサンスでは、人間そのものの個性や能力に光が当てられました。この考え方を【人文主義(ヒューマニズム)】といいます。\nなぜ14世紀の【イタリア】から始まったのでしょうか。理由は3つあります。第一に、東方貿易で栄えた都市に、フィレンツェの【メディチ家】のような大商人がいて、芸術家を保護する財力がありました。第二に、イタリアには古代ローマの遺跡が多く残っていました。第三に、ビザンツ帝国から逃れてきた学者などによって、ギリシアの古典研究がさかんになりました。\n文学では、【ダンテ】がラテン語ではなく、地方の言葉であるトスカナ語で『神曲』を書きました。ボッカチオは『デカメロン』で人間の欲望をありのままに描きました。\n美術では、【レオナルド=ダ=ヴィンチ】が「最後の晩餐」「モナ=リザ」を描き、科学や工学の研究も行って「万能の天才」とよばれました。【ミケランジェロ】は「ダヴィデ像」の彫刻や、システィナ礼拝堂の「最後の審判」を残し、【ラファエロ】は多くの聖母子像を描きました。ボッティチェリの「ヴィーナスの誕生」は、ギリシア神話を題材にしています。建築では、ブルネレスキがフィレンツェのサンタ=マリア大聖堂の大きなドームを設計しました。\n政治思想では、【マキァヴェリ】が『君主論』を書き、君主は国をまとめるためには道徳にとらわれず、力と策略を使うべきだと説きました。政治を宗教や道徳から切りはなして考えたのは、新しい見方でした。\nルネサンスは、16世紀にはアルプスの北にも広がりました。ネーデルラントの【エラスムス】は『愚神礼賛』で教会の腐敗を風刺し、イギリスのトマス=モアは『ユートピア』で社会を批判しました。イギリスのシェークスピア、スペインのセルバンテス(『ドン=キホーテ』)も活躍しました。\n科学技術では、15世紀半ばにドイツの【グーテンベルク】が活版印刷術を実用化し、書物が大量に安く作れるようになりました。ポーランドの【コペルニクス】は、地球が太陽のまわりを回るという【地動説】を唱え、教会が支持していた天動説に疑問を投げかけました。',
        key: 'ルネサンスはイタリアから(東方貿易の富・メディチ家などの保護、古代ローマの遺産、ギリシア古典研究)。人文主義。活版印刷(グーテンベルク)と地動説(コペルニクス)が新しい時代をひらいた。' },
      { h: '大航海時代:新しい航路と世界の一体化', t: '15世紀末から、ヨーロッパの国々は大西洋に乗り出し、アジアやアメリカ大陸への新しい航路を開きました。これを【大航海時代】といいます。\nなぜ、新しい航路が必要だったのでしょうか。ヨーロッパでは、肉の保存や味つけに使うアジアの【香辛料】がとても高く取り引きされていました。しかし、香辛料はイスラーム商人やイタリア商人を通じて運ばれ、さらにオスマン帝国が東地中海に勢力を広げたことで、ますます高価になりました。そこで、アジアと直接取り引きできる航路が求められたのです。ほかにも、キリスト教を広めたいという宗教的な動機、マルコ=ポーロの記録などによるアジアへの関心、羅針盤や遠洋航海に適した船などの航海技術の進歩が、この動きをささえました。また、レコンキスタを進めて国王の力が強まっていた【ポルトガル】と【スペイン】が、国家として航海を支援しました。\n【ポルトガル】は、アフリカの西海岸を南へ進むルートをとりました。エンリケ航海王子が航海を奨励し、1488年に【バルトロメウ=ディアス】がアフリカ南端の【喜望峰】に到達しました。1498年には【ヴァスコ=ダ=ガマ】が喜望峰を回ってインドの【カリカット】に到着し、インド航路が開かれました。ポルトガルはその後、インドのゴアやマラッカを拠点に香辛料貿易を行い、16世紀半ばには中国のマカオに居住権を得ました。1500年にはカブラルがブラジルに漂着し、ブラジルはポルトガル領になりました。\n【スペイン】は、西へ進めばアジアに着くと考えたイタリア人【コロンブス】を支援しました。コロンブスは1492年にカリブ海のサンサルバドル島に到達しました。彼はそこをインドの一部だと考えましたが、のちにアメリゴ=ヴェスプッチの調査で、ヨーロッパの知らなかった大陸であることが分かり、「アメリカ」とよばれるようになりました。1494年の【トルデシリャス条約】で、スペインとポルトガルは海外の領土の境界線を取り決めました。\n1519年にスペインを出発した【マゼラン】の船隊は、南アメリカ南端を回って太平洋をわたり、フィリピンに着きました。マゼラン自身はそこで戦死しましたが、部下が1522年にスペインにもどり、【世界周航】が達成されました。地球が丸いことが、実際の航海で確かめられたのです。\nスペインは、アメリカ大陸で【コルテス】がアステカ王国を(1521年)、【ピサロ】がインカ帝国を(1533年)征服しました。征服者たちは先住民を強制的に働かせ、ヨーロッパから持ちこまれた伝染病もあって、先住民の人口は激減しました。労働力の不足を補うため、のちにアフリカから多くの黒人奴隷が連れてこられました。1545年には、今のボリビアに【ポトシ銀山】が発見され、大量の銀がヨーロッパへ運ばれました。',
        key: '香辛料を直接手に入れるため新航路へ。ポルトガル=東回り(ディアス1488年喜望峰・ガマ1498年カリカット)、スペイン=西回り(コロンブス1492年・マゼラン船隊の世界周航1519〜22年)。アステカ・インカの征服とポトシ銀山。',
        chain: { title: '大航海時代がヨーロッパに与えた影響', items: [
          ['原因', '香辛料の需要・オスマン帝国の進出で東方の物産が高価に', '航海技術の進歩・国王の支援'],
          ['できごと', '新航路の開拓とアメリカ大陸の征服', 'ガマのインド到着(1498年)・コロンブス(1492年)'],
          ['結果1', '商業革命:貿易の中心が地中海から大西洋岸へ', 'リスボン・アントウェルペンが栄え、北イタリア諸都市は衰退'],
          ['結果2', '価格革命:アメリカ大陸の銀の流入で物価が上がる', '固定した地代に頼る領主が打撃・商工業者は利益'],
          ['結果3', '東ヨーロッパでは西欧向けの穀物生産のため農奴制が強化', 'エルベ川の東で農場領主制が広がる']] },
        ex: [{ q: 'ポルトガルとスペインが15世紀末に新しい航路を開こうとした理由を、オスマン帝国と関連づけて説明しよう。', hint: '香辛料がどのような道すじでヨーロッパに届いていたかを考えましょう。', steps: ['ヨーロッパでは、肉の保存などに使うアジアの香辛料が高い値段で取り引きされていた。', '香辛料は、イスラーム商人やイタリア商人の手をへて地中海経由で運ばれていた。', 'オスマン帝国が東地中海に勢力を広げ、東方の物産はさらに高価になった。', 'そこで、ポルトガルやスペインは、仲介する商人を通さずにアジアと直接取り引きできる航路を求めた。'], a: '香辛料などアジアの物産はイスラーム商人やイタリア商人を通じて運ばれ、オスマン帝国の東地中海進出でさらに高価になったため、アジアと直接取り引きできる新しい航路を求めたから。', check: '「香辛料の需要」と「オスマン帝国による入手の困難」の両方が理由として入っているかを確かめます。' }] },
      { h: '宗教改革:カトリック教会の分裂', t: '16世紀の初め、教皇【レオ10世】は、ローマのサン=ピエトロ大聖堂の改築の費用を集めるため、【贖宥状(免罪符)】を販売しました。「これを買えば罪のつぐないが軽くなる」とされた証書です。とくにドイツでは、皇帝の力が弱く国としてまとまっていなかったため、大量に販売されました。\n1517年、ヴィッテンベルク大学の神学教授【ルター】は、【九十五か条の論題】を発表して、贖宥状の販売を批判しました。ルターは、人が救われるのは善行や贖宥状によるのではなく、神への【信仰によってのみ】であるという【信仰義認説】を説き、信仰のよりどころは教会の教えではなく【聖書だけ】であるとしました。\nルターの主張は、活版印刷によるパンフレットで急速に広まりました。教皇から破門され、1521年のヴォルムス帝国議会で神聖ローマ皇帝【カール5世】から自説の撤回を求められましたが、ルターはこれを拒みました。ザクセン選帝侯にかくまわれたルターは、『新約聖書』をドイツ語に翻訳し、一般の人々が聖書を読めるようにしました。\n1524年には、ルターの改革に刺激されたミュンツァーらの指導で【ドイツ農民戦争】が起こり、農民が農奴制の廃止などを求めました。ルターは、はじめは同情したものの、反乱が激しくなると諸侯の側につき、反乱はおさえられました。\nその後、ルター派の諸侯とカトリックの皇帝の争いが続き、1555年の【アウクスブルクの和議】で決着しました。これにより、【諸侯】はカトリックかルター派のどちらかを選ぶことができ、領民はその選んだ宗派に従うことになりました。ただし、個人に信仰の自由が認められたわけではなく、カルヴァン派も認められませんでした。\nスイスのジュネーヴでは、【カルヴァン】が改革を行いました。カルヴァンは、だれが救われるかはあらかじめ神によって決められているという【予定説】を説きました。人々は、自分が救われる側にいると信じて、神から与えられた職業に励むことが大切だとされ、その結果として得た利益(蓄財)も肯定されました。そのため、カルヴァン派は商工業者に広く受け入れられ、フランスでは【ユグノー】、イングランドでは【ピューリタン】、スコットランドでは【プレスビテリアン】、ネーデルラントでは【ゴイセン】とよばれました。\nイギリスでは、国王【ヘンリ8世】が自分の離婚問題で教皇と対立し、1534年の【首長法】で、国王を首長とする【イギリス国教会】をつくりました。その後、【エリザベス1世】が1559年の統一法で、国教会の制度を確立しました。\nカトリック側も、勢力を立て直すための改革(【対抗宗教改革】)を行いました。【トリエント公会議】(1545〜63年)で教皇の権威とカトリックの教えを再確認し、【イグナティウス=ロヨラ】らがつくった【イエズス会】は、海外での布教に力を入れました。その一員の【フランシスコ=ザビエル】は、1549年に日本に来てキリスト教を伝えました。',
        key: 'ルター(1517年・信仰義認説・聖書主義)→ アウクスブルクの和議(1555年・諸侯が宗派を選ぶ・カルヴァン派は除外)。カルヴァン(予定説・蓄財の肯定で商工業者に広まる)。イギリス国教会(1534年首長法)。対抗宗教改革(トリエント公会議・イエズス会)。',
        flow: { title: '宗教改革で生まれた宗派(16世紀)', cols: 3, head: ['宗派', '始めた人・きっかけ', '広まった地域・人々'], rows: [
          [['ルター派', 'r'], ['ルター(1517年)', 'r', 1, '信仰義認説・聖書主義'], ['北ドイツ・北欧', 'r', 1, '諸侯が採用(1555年に公認)']],
          [['カルヴァン派', 'b'], ['カルヴァン(ジュネーヴ)', 'b', 1, '予定説・蓄財の肯定'], ['商工業者', 'b', 1, 'ユグノー・ピューリタン・ゴイセンなど']],
          [['イギリス国教会', 'g'], ['ヘンリ8世(1534年首長法)', 'g', 1, '国王が教会の首長'], ['イギリス', 'g', 1, 'エリザベス1世の統一法(1559年)']],
          [['カトリック(対抗宗教改革)', 'o'], ['トリエント公会議・イエズス会', 'o', 1, '教皇の権威を再確認'], ['南欧・海外布教', 'o', 1, 'ザビエルが日本へ(1549年)']]
        ], legend: [['r', 'ルター派'], ['b', 'カルヴァン派'], ['g', 'イギリス国教会'], ['o', 'カトリック']] } },
      { h: '主権国家体制:イタリア戦争から三十年戦争へ', t: '中世のヨーロッパには、教皇や皇帝という、国をこえた権威がありました。近世になると、それぞれの国が、はっきりした国境(領域)の中で、ほかのどんな権力からも命令されない最高の権力、つまり【主権】をもつようになりました。こうした国を【主権国家】といい、主権国家どうしが対等な立場で並び立ち、外交や戦争を通じて関係をもつしくみを【主権国家体制】といいます。\n主権国家体制が形づくられるきっかけになったのが、【イタリア戦争】(1494〜1559年)です。フランス王がイタリアに侵入し、神聖ローマ皇帝(スペイン王を兼ねたハプスブルク家)と、イタリアの支配権をめぐって長く争いました。この戦争の中で、各国は常設の外交使節をおき、同盟を結んだり破ったりして、勢力のつり合いをとる外交を行うようになりました。\n主権国家体制が確立したのは、【三十年戦争】(1618〜48年)の結果です。この戦争は、神聖ローマ帝国内のベーメン(ボヘミア)の新教徒が、カトリックを強制するハプスブルク家に反乱を起こしたことから始まりました。はじめは宗教戦争でしたが、デンマークやスウェーデンが新教徒側で参戦し、さらにカトリック国のフランスまでが、ハプスブルク家に対抗するために新教徒側について参戦しました。宗教よりも【国の利害】が優先される国際戦争になったのです。\n1648年の【ウェストファリア条約】で、三十年戦争は終わりました。この条約では、(1)アウクスブルクの和議の原則が確認され、カルヴァン派も公認されました。(2)スイスとオランダの独立が正式に認められました。(3)フランスはアルザスの大部分を、スウェーデンは西ポンメルンなどを得ました。(4)神聖ローマ帝国内の約300の【領邦】は、ほぼ完全な主権を認められ、神聖ローマ帝国は事実上形だけのものになりました。\nこの条約は、多くの国が参加した国際会議で結ばれ、それぞれの国の主権と領土が確認されました。そのため、ウェストファリア条約は【主権国家体制の確立】を示すものとされています。',
        key: '主権国家=国境の中で最高の権力(主権)をもつ国。イタリア戦争(1494〜1559年)で外交のしくみができ、三十年戦争(1618〜48年)後のウェストファリア条約で主権国家体制が確立。神聖ローマ帝国は形だけに。',
        ex: [{ q: 'ウェストファリア条約が「主権国家体制の確立」を示すとされるのはなぜか。説明しよう。', hint: '条約で、神聖ローマ帝国の中の領邦はどうなったでしょうか。', steps: ['三十年戦争は、宗教戦争として始まったが、国の利害を優先する国際戦争になった。', '戦争を終わらせるため、多くの国が参加する国際会議でウェストファリア条約が結ばれた。', 'この条約で、スイス・オランダの独立が認められ、神聖ローマ帝国内の領邦もほぼ完全な主権を認められた。', 'つまり、皇帝や教皇のような国をこえた権威ではなく、それぞれの国の主権と領土を互いに認め合う関係が確認された。'], a: '多くの国が参加した国際会議で、スイス・オランダの独立や領邦の主権が認められ、国をこえた皇帝や教皇の権威ではなく、主権をもつ国どうしが互いの主権と領土を認め合うしくみが確認されたから。', check: '「国をこえた権威の後退」と「主権の相互承認」の両方が入っているかを確かめます。' }] },
      { h: '絶対王政:スペイン・オランダ・イギリス・フランス', t: '主権国家の中で、国王が強い権力をにぎって国を治める政治のしくみを【絶対王政】といいます。絶対王政をささえたのは、国王の命令で動く【官僚制】と、国王が直接もつ【常備軍】でした。これらを維持するには多くのお金が必要なため、国王は、輸出を増やし輸入をおさえて国内に金銀をたくわえようとする【重商主義】の政策をとりました。また、国王の権力は神から与えられたものだとする【王権神授説】が、絶対王政を正当化しました。\nただし、絶対王政といっても、国王が何でも思いどおりにできたわけではありません。貴族・聖職者・都市・ギルドなどの【社団】とよばれる集団がもつ特権を認めながら、それらを通じて国を治めていました。\n【スペイン】は、16世紀に最も栄えました。カルロス1世は、神聖ローマ皇帝カール5世を兼ねました。その子【フェリペ2世】は、1571年の【レパントの海戦】でオスマン帝国の海軍を破り、1580年にはポルトガルを併合して、「太陽の沈まぬ国」とよばれました。しかし、カトリックを強制したことに反発した【オランダ】(ネーデルラント)が独立戦争を起こしました(1568年〜)。北部7州はユトレヒト同盟を結び(1579年)、1581年に独立を宣言しました。\n独立した【オランダ】は、1602年に東インド会社を設立し、首都アムステルダムは17世紀前半、世界の商業と金融の中心として栄えました。\n【イギリス】では、【エリザベス1世】が1588年にスペインの【無敵艦隊(アルマダ)】を破り、1600年に東インド会社を設立して、海外進出の土台をつくりました。毛織物工業もさかんになりました。\n【フランス】では、カトリックとユグノーの対立から【ユグノー戦争】(1562〜98年)が起こり、1572年のサンバルテルミの虐殺では多くのユグノーが殺されました。ブルボン朝を開いた【アンリ4世】は、自らカトリックに改宗する一方、1598年の【ナントの王令】でユグノーにも信仰の自由を認めて、内乱を終わらせました。ルイ13世の時代には、1614〜15年の会議を最後に三部会は開かれなくなり、のちに宰相となったリシュリューのもとで王権が強化されました。\nフランスの絶対王政は、【ルイ14世】の時代に最盛期をむかえました。「太陽王」とよばれたルイ14世は、財務総監【コルベール】のもとで重商主義政策を進め、壮大な【ヴェルサイユ宮殿】を建てました。しかし、1685年にナントの王令を廃止したため、商工業者の多いユグノーが国外に逃れ、フランスの産業は打撃を受けました。また、たび重なる対外戦争で財政は苦しくなりました。孫をスペイン王にしたことから起こった【スペイン継承戦争】(1701〜13年)は、1713年のユトレヒト条約で終わり、孫のスペイン王位は認められましたが、フランスとスペインは合同しないことが約束されました。',
        key: '絶対王政=官僚制+常備軍、重商主義と王権神授説、社団を通じた支配。スペイン(フェリペ2世)→ オランダの独立(東インド会社1602年)→ イギリス(エリザベス1世・1588年無敵艦隊撃破)→ フランス(アンリ4世のナントの王令・ルイ14世が最盛期)。' },
      { h: '東ヨーロッパの絶対王政:プロイセン・オーストリア・ロシア', t: '17〜18世紀には、東ヨーロッパでも強い国王のもとで国づくりが進みました。東ヨーロッパの国々は、西ヨーロッパに比べて市民階層が育っておらず、大航海時代以降、西ヨーロッパ向けの穀物をつくるために農奴制が強められていました。そのため、国王は、農奴を支配する貴族(プロイセンではユンカーとよばれる地主貴族)と協力して国を治めました。\n東ヨーロッパの君主の中には、フランスで生まれた啓蒙思想の影響を受け、「上からの改革」で国を近代化しようとした人々がいました。これを【啓蒙専制君主】といいます。\n【プロイセン】の【フリードリヒ2世(大王)】は、「君主は国家第一の僕(しもべ)」と述べ、宗教への寛容や産業の育成を進めました。一方で、【オーストリア継承戦争】(1740〜48年)ではオーストリアの資源豊かな【シュレジエン】を奪い、その後の【七年戦争】(1756〜63年)でもシュレジエンを守りぬいて、プロイセンをヨーロッパの強国にしました。\n【オーストリア】では、ハプスブルク家の【マリア=テレジア】がオーストリア継承戦争で家督を守りました。シュレジエンを取りもどすため、長年の敵だったフランスと手を結び(外交革命)、七年戦争を戦いましたが、シュレジエンは取りもどせませんでした。その子ヨーゼフ2世は、農奴解放などの改革を試みた啓蒙専制君主として知られます。\n【ロシア】では、【ピョートル1世(大帝)】が自ら西ヨーロッパを視察し、技術や制度を取り入れて西欧化を進めました。【北方戦争】(1700〜21年)でスウェーデンを破ってバルト海に進出し、新しい都【ペテルブルク】を建設しました。東方では、1689年に清と【ネルチンスク条約】を結んで国境を定めました。18世紀後半の【エカチェリーナ2世】は、啓蒙専制君主として知られますが、農民反乱(プガチョフの乱)ののちは貴族との結びつきを強め、農奴制はかえって強化されました。黒海北岸に進出し、日本にもラクスマンを派遣しました。\n【ポーランド】は、貴族の力が強く、国王を選挙で選ぶ選挙王政のため、国王の権力が弱いままでした。その結果、ロシア・プロイセン・オーストリアによって、1772年・1793年・1795年の3回にわたって分割され、国が消滅しました(【ポーランド分割】)。強い主権国家をつくれなかった国が、周辺の強国にのみこまれた例です。',
        key: '東欧は市民階層が弱く農奴制が強化され、君主は貴族と協力。啓蒙専制君主:フリードリヒ2世(シュレジエン獲得)、ヨーゼフ2世、エカチェリーナ2世。ピョートル1世の西欧化と北方戦争。ポーランド分割(1772・93・95年)。' },
      { h: 'もっと深く:大航海時代は、なぜ東西ヨーロッパを分けたのか', t: '大航海時代の影響は、ヨーロッパの中でも地域によって正反対に表れました。そのしくみを、【商業革命】と【価格革命】の2つから考えてみましょう。\n【商業革命】とは、貿易の中心が地中海から大西洋岸へ移ったことです。アジアやアメリカとの貿易は大西洋を通って行われるようになり、ポルトガルのリスボン、のちにはネーデルラントのアントウェルペン、さらにアムステルダムが栄えました。一方、東方貿易で栄えたヴェネツィアなど北イタリアの都市は、しだいに衰えていきました。取り引きされる商品も、香辛料だけでなく、砂糖・タバコ・コーヒーなど、世界中の産物に広がりました。\n【価格革命】とは、アメリカ大陸からポトシ銀山などの大量の銀が流れこんだことで、ヨーロッパの物価が大きく上がったことです。物価が上がると、毎年決まった額の地代を受け取っている領主は、実際に買えるものが減るため、打撃を受けました。反対に、商品を売る商工業者は利益を得ました。こうして、西ヨーロッパでは封建的な領主の力が弱まり、商工業が発展しました。\nでは、東ヨーロッパではどうなったのでしょうか。西ヨーロッパで商工業が発達し、都市の人口が増えると、穀物の需要が高まりました。エルベ川より東の地域(プロイセン・ポーランドなど)の領主は、西ヨーロッパへ輸出するための穀物を大農場でつくるようになり、そのために農民への束縛をかえって強めました。これを【農場領主制(グーツヘルシャフト)】といい、「再版農奴制」ともよばれます。\nつまり、同じ大航海時代の変化が、西ヨーロッパでは【商工業の発展と領主の没落】、東ヨーロッパでは【穀物生産のための農奴制の強化】をもたらしたのです。西ヨーロッパが商工業の中心、東ヨーロッパがその穀物の供給地という分業が生まれ、のちの西と東の発展の差につながっていきました。前の節で、東ヨーロッパの君主が農奴を支配する貴族と協力したのは、このような経済のしくみが背景にあったからです。',
        key: '商業革命=貿易の中心が地中海から大西洋岸へ。価格革命=銀の流入で物価が上がり、固定地代の領主が打撃。東欧では西欧向け穀物生産のため農奴制が強化(農場領主制)。' },
      { h: '入試ではこう出る:宗教改革と主権国家の正誤・論述', t: 'この分野の入試では、【条約・和議の内容】が正誤問題でよく問われます。アウクスブルクの和議(1555年)は「諸侯がカトリックかルター派を選ぶ・カルヴァン派は認められない・個人の信仰の自由ではない」、ウェストファリア条約(1648年)は「カルヴァン派の公認・スイスとオランダの独立承認・領邦の主権・神聖ローマ帝国の形骸化」、ナントの王令(1598年)は「ユグノーにも信仰を認める・1685年に廃止」と、それぞれの「認めたこと」と「認めなかったこと」をおさえましょう。\n人物の取りちがえもよくねらわれます。「ルター=信仰義認説、カルヴァン=予定説」「ヘンリ8世=首長法(国教会の成立)、エリザベス1世=統一法(国教会の確立)」「アンリ4世=ナントの王令、ルイ14世=ナントの王令の廃止」のように、似た立場の人物を対にして覚えるのがコツです。\n大航海時代では、【航海者と到達地・年代】の組み合わせが定番です。ディアス=喜望峰(1488年)、コロンブス=サンサルバドル島(1492年)、ガマ=カリカット(1498年)、マゼラン船隊=世界周航(1519〜22年)を、ポルトガル(東回り)とスペイン(西回り)に分けて整理しましょう。\n論述では、「宗教改革が広まった理由」「大航海時代が東西ヨーロッパに与えた影響のちがい」「三十年戦争が宗教戦争から国際戦争に変わった理由」がよく出ます。三十年戦争については、カトリック国のフランスが新教徒側で参戦したことを、具体的な根拠として必ず入れましょう。',
        key: '和議・条約は「認めたこと」と「認めなかったこと」をセットで。似た立場の人物は対にして覚える。三十年戦争の論述では、カトリック国フランスの新教側での参戦を根拠に。',
        ex: [
          { q: '次の文の正誤を判断し、誤りがあれば正しく直そう。「1555年のアウクスブルクの和議で、ルター派とカルヴァン派が公認され、個人が自由に信仰を選べるようになった。」', hint: 'アウクスブルクの和議で、宗派を選ぶことができたのはだれでしょうか。', steps: ['アウクスブルクの和議では、ルター派が認められた。', 'しかし、カルヴァン派は認められなかった(公認されたのは1648年のウェストファリア条約)。', 'また、宗派を選ぶことができたのは諸侯であり、領民は諸侯の選んだ宗派に従った。', 'したがって、「カルヴァン派が公認」と「個人が自由に信仰を選べる」の2か所が誤り。'], a: '誤り。公認されたのはルター派だけで、カルヴァン派は認められなかった。また、宗派を選べたのは諸侯で、個人の信仰の自由は認められなかった。', check: '誤りが1か所とは限らないので、文を要素ごとに区切って、すべての要素を確かめます。' },
          { q: '三十年戦争が、宗教戦争から国際戦争へと性格を変えたことを示す具体的な事実を挙げて説明しよう。', hint: 'フランスはカトリックとプロテスタントのどちらの国で、どちらの側について参戦したでしょうか。', steps: ['三十年戦争は、ベーメンの新教徒がカトリックを強制するハプスブルク家に反乱を起こしたことから始まった宗教戦争だった。', 'その後、デンマークやスウェーデンが新教徒側で参戦し、戦争は国際的に広がった。', 'さらに、カトリックの国であるフランスが、ハプスブルク家に対抗するため、新教徒側について参戦した。', '宗教が同じカトリックでありながら敵味方に分かれたことは、宗教より国の利害が優先されたことを示している。'], a: 'カトリック国のフランスが、ハプスブルク家に対抗するために新教徒側について参戦したことから、宗教より国の利害が優先される国際戦争へと性格が変わったことが分かる。', check: '「カトリック国のフランスが新教徒側についた」という、宗教の対立では説明できない事実が入っているかを確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '1488年に喜望峰に到達した人物と、1498年にインドのカリカットに到達した人物を答えよう。', a: '1488年=バルトロメウ=ディアス、1498年=ヴァスコ=ダ=ガマ(ともにポルトガル)', exp: 'ポルトガルは、アフリカ西岸を南下する東回りのルートでインドをめざしました。ディアスが喜望峰に到達し、その10年後にガマが喜望峰を回ってインドに着きました。\n同じころ、スペインの支援を受けたコロンブスが西回りで1492年にアメリカ大陸の島に到達しています。1488 → 1492 → 1498 の順番で、ポルトガルとスペインを交互に並べて覚えましょう。' },
      { lv: 1, q: 'ルイ14世のもとで重商主義政策を進めた財務総監はだれか。', a: 'コルベール', exp: 'コルベールは、国内の産業を保護・育成し(王立マニュファクチュアなど)、東インド会社を再建して、輸出を増やそうとしました。\n重商主義は、国内に金銀をたくわえて国を豊かにし、官僚制や常備軍の費用をまかなうための政策です。絶対王政のしくみと結びつけて理解しましょう。' },
      { lv: 2, q: 'ルネサンスがイタリアから始まった理由を、3つ挙げて説明しよう。', a: '(1)東方貿易で栄えた都市に、メディチ家のような芸術家を保護する大商人がいた。(2)古代ローマの遺跡や伝統が多く残っていた。(3)ビザンツ帝国から逃れた学者などを通じて、ギリシアの古典研究がさかんになった。', exp: 'ルネサンスには、芸術家を保護する「お金」、手本となる「古典」、それを研究する「人」が必要でした。イタリアには、その3つがそろっていました。\n東方貿易は十字軍のころから発展したもので、中世ヨーロッパの単元で学んだ内容とつながっています。ビザンツ帝国が1453年に滅びたことも、ギリシアの学者がイタリアに移るきっかけの一つになりました。' },
      { lv: 2, q: 'カルヴァン派が商工業者に広く受け入れられた理由を説明しよう。', a: 'カルヴァンの予定説では、神から与えられた職業に励むことが大切とされ、その結果として得た利益(蓄財)も肯定されたため、勤勉に働いて利益を得る商工業者の生き方と合っていたから。', exp: '中世のカトリック教会は、利益を追い求めることや利子を取ることに否定的でした。\nカルヴァン派では、救われるかどうかは神が決めているが、職業に励んで成功することは救われている証しと考えられるようになりました。そのため、商工業者は安心して商売に励むことができました。\nこのため、カルヴァン派は、商工業の発達したフランス・ネーデルラント・イングランドなどに広まりました。' },
      { lv: 3, q: '大航海時代が西ヨーロッパと東ヨーロッパの社会にもたらした影響のちがいを、80字程度で説明しよう。(記述)', a: '(模範解答)西ヨーロッパでは、銀の流入による価格革命で固定地代に頼る領主が没落し、商工業が発展した。東ヨーロッパでは、西欧向けの穀物を生産するため、領主が農奴への束縛を強める農場領主制が広がった。(91字)', exp: '同じ大航海時代でも、西と東では正反対の結果になりました。\n西ヨーロッパでは、アメリカ大陸の銀の流入で物価が上がり(価格革命)、決まった地代を受け取る領主は実質的な収入が減りました。一方、商工業者は利益を得ました。また、貿易の中心も大西洋岸に移りました(商業革命)。\n東ヨーロッパでは、西ヨーロッパの都市の人口増加で穀物の需要が高まり、エルベ川以東の領主は輸出用の穀物をつくる大農場を経営して、農民への束縛を強めました(農場領主制・再版農奴制)。\n採点のポイントは、(1)西欧=価格革命と領主の没落・商工業の発展、(2)東欧=西欧向け穀物生産、(3)東欧=農奴制の強化(農場領主制)、の3点です。' },
      { lv: 3, q: '絶対王政のしくみを、それをささえた制度と考え方に注目して説明しよう。また、「絶対」といっても国王の権力に限界があった点にもふれよう。(記述)', a: '(模範解答)絶対王政は、国王の命令で動く官僚制と、国王が直接もつ常備軍にささえられ、その費用をまかなうために重商主義政策がとられた。国王の権力は神から与えられたとする王権神授説が、これを正当化した。ただし、国王は貴族・聖職者・都市・ギルドなどの社団の特権を認め、それらを通じて国を治めていたため、権力は無制限ではなかった。', exp: '絶対王政を説明するときは、「何によってささえられたか(官僚制・常備軍)」「その費用をどうまかなったか(重商主義)」「どう正当化されたか(王権神授説)」の3つをそろえます。\nさらに、近年の教科書では、絶対王政が「社団」を通じた支配だったことも重視されています。国王はすべての人を直接支配したのではなく、身分や地域ごとの特権をもつ集団を認め、それを利用して統治しました。\n採点のポイントは、(1)官僚制と常備軍、(2)重商主義、(3)王権神授説、(4)社団の特権を認めた支配という限界、の4点です。(4)まで書けると、より高い評価になります。' }
    ],
    faq: [
      ['ルネサンスとヒューマニズムは同じ意味?', '同じではありません。【ルネサンス】は、14〜16世紀にイタリアから広がった文化運動全体を指すことばです。【人文主義(ヒューマニズム)】は、その中心にある考え方で、ギリシア・ローマの古典を研究して、人間らしい生き方を追い求めることを指します。\n「運動=ルネサンス、考え方=人文主義」と区別しましょう。'],
      ['宗教改革は、なぜドイツで始まったの?', '当時のドイツ(神聖ローマ帝国)は、多くの領邦に分かれ、皇帝の力が弱かったため、教皇がお金を集めやすい地域でした。そのため、贖宥状が大量に販売され、「ローマの牝牛」とよばれるほど富が吸い上げられていました。\nまた、皇帝と対立する諸侯の中には、ルターを保護することで教会の土地や権力を手に入れようとする者もいました。ザクセン選帝侯がルターをかくまったのは、その一例です。'],
      ['主権国家と、今の「国民国家」は同じもの?', '同じではありません。【主権国家】は、国境の中で最高の権力(主権)をもつ国のことで、近世の主権の持ち主は国王でした。【国民国家】は、その国に住む人々が「同じ国民だ」という意識をもってまとまる国のことで、フランス革命以降の19世紀に広がりました。\n近世の主権国家が土台となって、のちに国民国家へと発展していきます。']
    ],
    terms: [['人文主義', 'ギリシア・ローマの古典を研究し、人間らしい生き方を追い求める考え方。ルネサンスの中心'], ['贖宥状', '罪のつぐないが軽くなるとされた証書。免罪符ともいう'], ['信仰義認説', '人は信仰によってのみ救われるとするルターの教え'], ['予定説', '救われる人はあらかじめ神によって決められているとするカルヴァンの教え'], ['主権国家体制', '国境と主権をもつ国どうしが対等に並び立ち、外交や戦争で関係をもつしくみ'], ['重商主義', '輸出を増やし輸入をおさえて、国内に金銀をたくわえようとする経済政策'], ['王権神授説', '国王の権力は神から与えられたものだとする考え'], ['価格革命', 'アメリカ大陸の銀の流入で、16世紀のヨーロッパの物価が大きく上がったこと']],
    miss: ['アウクスブルクの和議で、個人の信仰の自由やカルヴァン派が認められたと思う。選べたのは諸侯で、カルヴァン派は除外。カルヴァン派の公認は1648年のウェストファリア条約。', 'ルターの「信仰義認説」とカルヴァンの「予定説」を逆にする。ルター=「信じれば救われる」、カルヴァン=「救いは神があらかじめ決めている」と、短いことばで区別する。', 'ナントの王令を出したのはルイ14世だと思う。出したのはアンリ4世(1598年)で、ルイ14世は廃止した(1685年)。「アンリが出し、ルイが廃止」と対で覚える。', 'マゼランが自分で世界一周をしてスペインに帰ったと思う。マゼランはフィリピンで戦死し、世界周航を達成したのは部下たち(1522年に帰国)。', '大航海時代で、東ヨーロッパでも農奴が解放されたと思う。東ヨーロッパでは西欧向けの穀物生産のため、農奴制はむしろ強化された(農場領主制)。'],
    sum: ['ルネサンスはイタリアから始まり、人文主義のもとで文学・美術・科学が発展し、活版印刷や地動説が新しい時代をひらいた。', '大航海時代には、ポルトガルが東回り、スペインが西回りで新航路を開き、商業革命と価格革命が起こった。', 'ルターの宗教改革からカトリック教会が分裂し、アウクスブルクの和議・カルヴァン派・イギリス国教会・対抗宗教改革へと展開した。', 'イタリア戦争と三十年戦争をへて、ウェストファリア条約(1648年)で主権国家体制が確立した。', '各国では官僚制・常備軍・重商主義・王権神授説にささえられた絶対王政が行われ、スペイン → オランダ・イギリス → フランスと覇権が移った。', '東ヨーロッパでは、農奴制を基盤に、啓蒙専制君主が上からの改革を進め、国王の力が弱いポーランドは分割された。'],
    next: '次は、近世のアジア(明・清、オスマン帝国・サファヴィー朝・ムガル帝国)を学ぶ単元(wh_asia_em)に進みましょう。ヨーロッパが大航海時代で海に乗り出したころ、アジアでは明・清、オスマン帝国・サファヴィー朝・ムガル帝国が栄えていました。ヨーロッパの商人がアジアの大帝国とどう向き合ったのかに注目します。'
  };
})(WPS.LESSONS);
